for s in seeds:
    candidates += [s, "---"+s, s+"---", "---"+s+"---", s+"\n|\n|", "|\n"+s, "|\n|\n"+s, s+"\n|", "/"+s, s+"/", "\\"+s, s+"\\", " "+s+"\n/", " "+s+"\n\\"]
# all pairs of chars followed/preceded by line
chars="<>^vVoO*#xX/\\|()[]{}+.,'`:;!-_=~"
for a in chars:
 for b in chars:
   candidates.append("---"+a+b)
   candidates.append(a+b+"---")
   candidates.append(a+b+"\n|")
   candidates.append("|\n"+a+b)
found={}
