import subprocess, itertools, random
random.seed(1)
def check(c, targets):
    p=subprocess.run(["./executable"],input=c.encode(),capture_output=True)
    body=p.stdout.decode().split("</defs>")[-1]
    hit=[t for t in targets if t in body]
    return hit,body
targets=["start_marked","diamond","marked_arrow"]
found={t:[] for t in targets}
cands=set()
# horizontal strings length up to 7 over small alphabet exhaustive maybe 8^5
alphabet="-><oO*#"
for n in range(2,7):
    for tup in itertools.product(alphabet, repeat=n):
        cands.add("".join(tup))
# vertical strings
alphabetv="|v^VoO*#:"
for n in range(2,6):
    for tup in itertools.product(alphabetv, repeat=n):
        cands.add("\n".join(tup))
# diagonal arrangements 3x3 random
chars=" -|/\\<>^vVoO*#.+xX"
for i in range(4000):
    rows=["".join(random.choice(chars) for _ in range(5)) for __ in range(3)]
    cands.add("\n".join(rows))
for i,c in enumerate(cands):
    hit,body=check(c,targets)
    for h in hit:
        if len(found[h])<20: found[h].append((c,body.strip().replace("\n"," ")[:300]))
print({k:len(v) for k,v in found.items()})
for k,v in found.items():
    print("\n",k)
    for c,b in v: print(repr(c),b)
