#[derive(Clone, Copy, PartialEq, Debug)]
struct Pt { x: f32, y: f32 }
impl Pt {
    fn new(x: f32, y: f32) -> Self { Pt{x,y} }
}
fn pt_eq(a: Pt, b: Pt) -> bool { (a.x-b.x).abs() < 0.001 && (a.y-b.y).abs() < 0.001 }

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum LineStyle { Solid, Broken }
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Marker { OpenCircle, BigOpenCircle, FilledCircle }
impl Marker {
    fn suffix(&self) -> &'static str {
        match self { Marker::OpenCircle=>"open_circle", Marker::BigOpenCircle=>"big_open_circle", Marker::FilledCircle=>"circle" }
    }
    fn from_char(c: char) -> Option<Marker> {
        match c { 'o'=>Some(Marker::OpenCircle), 'O'=>Some(Marker::BigOpenCircle), '*'=>Some(Marker::FilledCircle), _=>None }
    }
}

#[derive(Clone, Debug)]
enum ShapeKind {
    Line { a: Pt, b: Pt, style: LineStyle, marker_start: Option<Marker>, marker_end: Option<Marker> },
    Arc { a: Pt, b: Pt, r: f32, large: bool, sweep: bool },
    Circle { c: Pt, r: f32 },
    Rect { x: f32, y: f32, w: f32, h: f32, filled: bool, rx: f32 },
    Polygon { pts: Vec<Pt> },
    Text { cell_x: i32, cell_y: i32, s: String },
    Group(Vec<Shape>),
}
#[derive(Clone, Debug)]
struct Shape {
    kind: ShapeKind,
    seq: usize,
    // order position (y,x) of earliest constituent cell, scaled-ish for promoted sorting
    pos: (i32,i32),
    promoted: bool,
}
impl Shape {
    fn new(kind: ShapeKind, seq: usize, pos: (i32,i32)) -> Self { Shape{kind,seq,pos,promoted:false} }
}

// Grid
struct Grid {
    cells: HashMap<(i32,i32), char>,
    width: i32,
    height: i32,
}
impl Grid {
    fn parse(input: &str) -> Grid {
        let mut cells = HashMap::new();
        let mut max_x: i32 = 0;
        let mut max_y: i32 = 0;
        for (yi, line) in input.lines().enumerate() {
            let y = yi as i32;
            let mut x: i32 = 0;
            for c in line.chars() {
                let w = char_width(c) as i32;
                if !c.is_whitespace() && c != '\0' {
                    cells.insert((x,y), c);
                    if x+1 > max_x { max_x = x+1; }
                    if y+1 > max_y { max_y = y+1; }
                }
                x += w;
            }
        }
        if max_x < 1 { max_x = 1; }
        if max_y < 1 { max_y = 1; }
        Grid{cells, width:max_x, height:max_y}
    }
    fn get(&self, x:i32, y:i32) -> Option<char> { self.cells.get(&(x,y)).copied() }
    fn sorted_cells(&self) -> Vec<(i32,i32,char)> {
        let mut v: Vec<(i32,i32,char)> = self.cells.iter().map(|(&(x,y),&c)| (x,y,c)).collect();
        v.sort_by_key(|&(x,y,_)| (y,x));
        v
    }
}

fn in_set(c: Option<char>, set: &str) -> bool {
    match c { Some(ch) => set.contains(ch), None=>false }
}
fn is_blank(g:&Grid, used:&BTreeSet<(i32,i32)>, x:i32,y:i32) -> bool {
    if used.contains(&(x,y)) { return true; }
    g.get(x,y).is_none()
}

// cell geometry helpers
fn cell_pt(x:i32,y:i32, dx:f32, dy:f32) -> Pt { Pt::new(x as f32*8.0+dx, y as f32*16.0+dy) }
fn center(x:i32,y:i32)->Pt{cell_pt(x,y,4.0,8.0)}
fn west(x:i32,y:i32)->Pt{cell_pt(x,y,0.0,8.0)}
fn east(x:i32,y:i32)->Pt{cell_pt(x,y,8.0,8.0)}
fn north(x:i32,y:i32)->Pt{cell_pt(x,y,4.0,0.0)}
fn south(x:i32,y:i32)->Pt{cell_pt(x,y,4.0,16.0)}
fn nw(x:i32,y:i32)->Pt{cell_pt(x,y,0.0,0.0)}
fn ne(x:i32,y:i32)->Pt{cell_pt(x,y,8.0,0.0)}
fn sw(x:i32,y:i32)->Pt{cell_pt(x,y,0.0,16.0)}
fn se(x:i32,y:i32)->Pt{cell_pt(x,y,8.0,16.0)}
fn nf(x:i32,y:i32)->Pt{cell_pt(x,y,4.0,4.0)}
fn sf(x:i32,y:i32)->Pt{cell_pt(x,y,4.0,12.0)}
fn nwf(x:i32,y:i32)->Pt{cell_pt(x,y,2.0,4.0)}
fn nef(x:i32,y:i32)->Pt{cell_pt(x,y,6.0,4.0)}
fn swf(x:i32,y:i32)->Pt{cell_pt(x,y,2.0,12.0)}
fn sef(x:i32,y:i32)->Pt{cell_pt(x,y,6.0,12.0)}

// Neighbor sets (char constants observed through testing)
// A char to the east/west that presents a mid-edge (horizontal) connection point for '+'
const H_MID: &str = "oO#'*+,-.`~";
// A char below that presents a north-mid connection point
const NORTH_PORT: &str = "!#'*+:`|"; // chars: ! # ' * + : ` |
// A char above that presents a south-mid connection point
const SOUTH_PORT: &str = "!#*+.:|";

struct Ctx<'a> {
    g: &'a Grid,
    used: &'a BTreeSet<(i32,i32)>,
}
impl<'a> Ctx<'a> {
    fn ch(&self, x:i32,y:i32)->Option<char>{ self.g.get(x,y) }
    fn n(&self,x:i32,y:i32)->Option<char>{self.g.get(x,y-1)}
    fn s(&self,x:i32,y:i32)->Option<char>{self.g.get(x,y+1)}
    fn w(&self,x:i32,y:i32)->Option<char>{self.g.get(x-1,y)}
    fn e(&self,x:i32,y:i32)->Option<char>{self.g.get(x+1,y)}
    fn nw(&self,x:i32,y:i32)->Option<char>{self.g.get(x-1,y-1)}
    fn ne(&self,x:i32,y:i32)->Option<char>{self.g.get(x+1,y-1)}
    fn sw(&self,x:i32,y:i32)->Option<char>{self.g.get(x-1,y+1)}
    fn se(&self,x:i32,y:i32)->Option<char>{self.g.get(x+1,y+1)}
}

#[derive(Clone, Debug)]
enum Frag {
    Line(Pt,Pt,LineStyle,Option<Marker>),
    Arc(Pt,Pt,f32,bool,bool), // a,b,r,large,sweep
    Circle(Pt,f32),
    Rect(f32,f32,f32,f32,bool,f32),
    Polygon(Vec<Pt>),
    TextChar(char),
    Nothing,
}
fn line_frag(a:Pt,b:Pt)->Frag{Frag::Line(a,b,LineStyle::Solid,None)}
fn marked_line(a:Pt,b:Pt,m:Marker)->Frag{Frag::Line(a,b,LineStyle::Solid,Some(m))}

fn fragments_for(ctx:&Ctx, x:i32,y:i32,c:char) -> Vec<Frag> {
    let g = ctx.g;
    let _ = g;
    match c {
        '-' | '~' => {
            let style = if c=='~' {LineStyle::Broken} else {LineStyle::Solid};
            let wc = ctx.w(x,y);
            let ec = ctx.e(x,y);
            if let Some(m) = wc.and_then(|ch| if ch=='o'||ch=='O' {Marker::from_char(ch)} else {None}) {
                return vec![Frag::Line(east(x,y), center(x-1,y), style, Some(m))];
            }
            if let Some(m) = ec.and_then(Marker::from_char) {
                return vec![Frag::Line(west(x,y), center(x+1,y), style, Some(m))];
            }
            vec![Frag::Line(west(x,y), east(x,y), style, None)]
        }
        '|' | ':' | '!' => {
            if c==':' || c=='!' {
                let has = in_set(ctx.n(x,y),"!:|") || in_set(ctx.s(x,y),"!:|");
                if !has {
                    // ':'/'!' may still need to be represented as a marker stub source?
                    // stub for a south marker is generated by marker cell, not here.
                    return vec![Frag::TextChar(c)];
                }
                // check south marker (only '|' handles markers? test suggests ':' south o gives text colon + stub from o)
                // For ':'/'!' as a line, if south is marker, original likely behaves like '|'? We'll treat like '|'
                let style = LineStyle::Broken;
                if let Some(m) = ctx.s(x,y).and_then(Marker::from_char) {
                    // ':'/'!' only handle south marker if they themselves are activated by north too?
                    // We'll just do it when c=='|' equivalent case below; here fallthrough generic:
                    return vec![Frag::Line(north(x,y), center(x,y+1), style, Some(m))];
                }
                return vec![Frag::Line(north(x,y), south(x,y), style, None)];
            }
            // '|'
            if let Some(m) = ctx.s(x,y).and_then(Marker::from_char) {
                return vec![Frag::Line(north(x,y), center(x,y+1), LineStyle::Solid, Some(m))];
            }
            vec![line_frag(north(x,y), south(x,y))]
        }
        '/' => {
            if let Some(m) = ctx.sw(x,y).and_then(Marker::from_char) {
                return vec![Frag::Line(ne(x,y), center(x-1,y+1), LineStyle::Solid, Some(m))];
            }
            // NE neighbor is '#' : extend start to # SW focus? # generates connector, slash unchanged.
            vec![line_frag(ne(x,y), sw(x,y))]
        }
        '\\' => {
            if let Some(m) = ctx.se(x,y).and_then(Marker::from_char) {
                return vec![Frag::Line(nw(x,y), center(x+1,y+1), LineStyle::Solid, Some(m))];
            }
            vec![line_frag(nw(x,y), se(x,y))]
        }
        '_' => vec![line_frag(sw(x,y), se(x,y))],
        '=' => vec![
            Frag::Line(cell_pt(x,y,0.0,6.0), cell_pt(x,y,8.0,6.0), LineStyle::Solid, None),
            Frag::Line(cell_pt(x,y,0.0,10.0), cell_pt(x,y,8.0,10.0), LineStyle::Solid, None),
        ],
        '+' => {
            let mut frags = Vec::new();
            let has_w = in_set(ctx.w(x,y), H_MID);
            let has_e = in_set(ctx.e(x,y), H_MID);
            let has_n = in_set(ctx.n(x,y), SOUTH_PORT);
            let has_s = in_set(ctx.s(x,y), NORTH_PORT);
            let has_ne = in_set(ctx.ne(x,y), "X/");
            let has_sw = in_set(ctx.sw(x,y), "X/");
            let has_nw = in_set(ctx.nw(x,y), "X\\");
            let has_se = in_set(ctx.se(x,y), "X\\");
            if has_w || has_e {
                let a = if has_w {west(x,y)} else {center(x,y)};
                let b = if has_e {east(x,y)} else {center(x,y)};
                frags.push(line_frag(a,b));
            }
            if has_n || has_s {
                let a = if has_n {north(x,y)} else {center(x,y)};
                let b = if has_s {south(x,y)} else {center(x,y)};
                frags.push(line_frag(a,b));
            }
            if has_ne || has_sw {
                let a = if has_ne {ne(x,y)} else {center(x,y)};
                let b = if has_sw {sw(x,y)} else {center(x,y)};
                frags.push(line_frag(a,b));
            }
            if has_nw || has_se {
                let a = if has_nw {nw(x,y)} else {center(x,y)};
                let b = if has_se {se(x,y)} else {center(x,y)};
                frags.push(line_frag(a,b));
            }
            if frags.is_empty() { vec![Frag::TextChar(c)] } else { frags }
        }
        'X' => {
            let mut frags = Vec::new();
            let has_w = in_set(ctx.w(x,y), "-~");
            let has_e = in_set(ctx.e(x,y), "-~");
            let has_n = in_set(ctx.n(x,y), "!:|");
            let has_s = in_set(ctx.s(x,y), "!:|");
            let has_ne = in_set(ctx.ne(x,y), "X/");
            let has_sw = in_set(ctx.sw(x,y), "X/");
            let has_nw = in_set(ctx.nw(x,y), "X\\");
            let has_se = in_set(ctx.se(x,y), "X\\");
            if has_w || has_e {
                let a = if has_w {west(x,y)} else {center(x,y)};
                let b = if has_e {east(x,y)} else {center(x,y)};
                frags.push(line_frag(a,b));
            }
            if has_n || has_s {
                let a = if has_n {north(x,y)} else {center(x,y)};
                let b = if has_s {south(x,y)} else {center(x,y)};
                frags.push(line_frag(a,b));
            }
            if has_ne || has_sw {
                let a = if has_ne {ne(x,y)} else {center(x,y)};
                let b = if has_sw {sw(x,y)} else {center(x,y)};
                frags.push(line_frag(a,b));
            }
            if has_nw || has_se {
                let a = if has_nw {nw(x,y)} else {center(x,y)};
                let b = if has_se {se(x,y)} else {center(x,y)};
                frags.push(line_frag(a,b));
            }
            if frags.is_empty() { vec![Frag::TextChar(c)] } else { frags }
        }
        '(' => {
            let nport = in_set(ctx.n(x,y), SOUTH_PORT);
            let sport = in_set(ctx.s(x,y), NORTH_PORT);
            // optional horizontal through line
            let through = in_set(ctx.w(x,y), "-~+") && in_set(ctx.e(x,y), "-~+");
            let mut frags = Vec::new();
            if sport {
                frags.push(Frag::Arc(north(x,y), south(x,y), 12.0, false, false));
            } else if nport {
                return vec![Frag::TextChar(c)];
            } else {
                frags.push(Frag::Arc(east(x,y), cell_pt(x,y,8.0,16.0), 16.0, false, false));
            }
            if through { frags.push(line_frag(west(x,y), east(x,y))); }
            frags
        }
        ')' => {
            let nport = in_set(ctx.n(x,y), SOUTH_PORT);
            let sport = in_set(ctx.s(x,y), NORTH_PORT);
            let through = in_set(ctx.w(x,y), "-~+") && in_set(ctx.e(x,y), "-~+");
            let mut frags = Vec::new();
            if nport && sport {
                frags.push(Frag::Arc(north(x,y), south(x,y), 12.0, false, true));
            } else if nport || sport {
                return vec![Frag::TextChar(c)];
            } else {
                frags.push(Frag::Arc(west(x,y), cell_pt(x,y,0.0,16.0), 16.0, false, true));
            }
            if through { frags.push(line_frag(west(x,y), east(x,y))); }
            frags
        }
        '.' => {
            let mut frags = Vec::new();
            let has_e = in_set(ctx.e(x,y), H_MID);
            let has_w = in_set(ctx.w(x,y), H_MID);
            let has_s = in_set(ctx.s(x,y), NORTH_PORT);
            let swc = ctx.sw(x,y);
            let sec = ctx.se(x,y);
            let has_sw_paren = swc==Some('(');
            let has_se_paren = sec==Some(')');
            let has_sw_diag = has_sw_paren || (swc==Some('/') && has_e);
            let has_se_diag = has_se_paren || (sec==Some('\\') && has_w);
            let mut stub_s = false;
            // W-S arc then E-S arc (order observed)
            if has_w && has_s {
                frags.push(Frag::Arc(west(x,y), sf(x,y), 4.0, false, true));
                stub_s = true;
            }
            if has_e && has_s {
                frags.push(Frag::Arc(east(x,y), sf(x,y), 4.0, false, false));
                stub_s = true;
            }
            if stub_s { frags.push(line_frag(sf(x,y), south(x,y))); }
            // diagonal arcs (only if no south-arc? In octagon no south char)
            if !has_s {
                if has_sw_diag {
                    frags.push(Frag::Arc(east(x,y), swf(x,y), 8.0, false, false));
                    frags.push(line_frag(swf(x,y), sw(x,y)));
                }
                if has_se_diag {
                    frags.push(Frag::Arc(west(x,y), sef(x,y), 8.0, false, true));
                    frags.push(line_frag(sef(x,y), se(x,y)));
                }
            }
            if frags.is_empty() {
                if in_set(ctx.s(x,y), "!:|") {
                    return vec![line_frag(sf(x,y), south(x,y))];
                }
                return vec![Frag::TextChar(c)];
            }
            frags
        }
        ',' => {
            let mut frags = Vec::new();
            let has_e = in_set(ctx.e(x,y), H_MID);
            let has_s = in_set(ctx.s(x,y), NORTH_PORT);
            let swc = ctx.sw(x,y);
            if has_e && has_s {
                frags.push(Frag::Arc(east(x,y), sf(x,y), 4.0, false, false));
                frags.push(line_frag(sf(x,y), south(x,y)));
            } else if swc==Some('(') {
                // small diagonal arc like '.'
                frags.push(Frag::Arc(east(x,y), swf(x,y), 8.0, false, false));
                frags.push(line_frag(swf(x,y), sw(x,y)));
            } else if swc==Some('/') && has_e {
                frags.push(Frag::Arc(east(x,y), swf(x,y), 8.0, false, false));
                frags.push(line_frag(swf(x,y), sw(x,y)));
            }
            if frags.is_empty() { vec![Frag::TextChar(c)] } else { frags }
        }
        '\'' => {
            let mut frags = Vec::new();
            let has_e = in_set(ctx.e(x,y), H_MID);
            let has_w = in_set(ctx.w(x,y), H_MID);
            let has_n = in_set(ctx.n(x,y), SOUTH_PORT);
            let nwc = ctx.nw(x,y);
            let nec = ctx.ne(x,y);
            let mut stub_n = false;
            // diagonal arcs first? Observed stub line before arc in shape order for NW case
            if nwc==Some('(') || nwc==Some('\\') {
                frags.push(line_frag(nw(x,y), nwf(x,y)));
                frags.push(Frag::Arc(nwf(x,y), east(x,y), 8.0, false, false));
                return frags;
            }
            if nec==Some(')') || nec==Some('/') {
                frags.push(line_frag(ne(x,y), nef(x,y)));
                frags.push(Frag::Arc(nef(x,y), west(x,y), 8.0, false, true));
                return frags;
            }
            if has_n && has_w {
                frags.push(Frag::Arc(nf(x,y), west(x,y), 4.0, false, true));
                stub_n = true;
            }
            if has_n && has_e {
                frags.push(Frag::Arc(nf(x,y), east(x,y), 4.0, false, false));
                stub_n = true;
            }
            if stub_n {
                // insert stub at front? Shape seeding: north line usually already seeded.
                frags.insert(0, line_frag(north(x,y), nf(x,y)));
            }
            if frags.is_empty() {
                if in_set(ctx.n(x,y), "!:|") {
                    return vec![line_frag(north(x,y), nf(x,y))];
                }
                return vec![Frag::TextChar(c)];
            }
            frags
        }
        '`' => {
            let has_e = in_set(ctx.e(x,y), H_MID);
            let has_n = in_set(ctx.n(x,y), SOUTH_PORT);
            let nwc = ctx.nw(x,y);
            if nwc==Some('(') || nwc==Some('\\') {
                return vec![line_frag(nw(x,y), nwf(x,y)), Frag::Arc(nwf(x,y), east(x,y), 8.0, false, false)];
            }
            if has_n && has_e {
                return vec![line_frag(north(x,y), nf(x,y)), Frag::Arc(nf(x,y), east(x,y), 4.0, false, false)];
            }
            vec![Frag::TextChar(c)]
        }
        '<' => {
            let has_e = in_set(ctx.e(x,y), "oO#'*+-.~");
            let has_w = in_set(ctx.w(x,y), "oO#*+-~");
            if has_e {
                vec![Frag::Polygon(vec![cell_pt(x,y,8.0,4.0), west(x,y), cell_pt(x,y,8.0,12.0)])]
            } else if has_w {
                vec![
                    line_frag(cell_pt(x,y,8.0,4.0), west(x,y)),
                    line_frag(west(x,y), cell_pt(x,y,8.0,12.0)),
                ]
            } else { vec![Frag::TextChar(c)] }
        }
        '>' => {
            let has_w = in_set(ctx.w(x,y), "oO#*+-.`~");
            let has_e = in_set(ctx.e(x,y), "oO#*+-~");
            if has_w {
                vec![Frag::Polygon(vec![cell_pt(x,y,0.0,4.0), east(x,y), cell_pt(x,y,0.0,12.0)])]
            } else if has_e {
                vec![
                    line_frag(cell_pt(x,y,0.0,4.0), east(x,y)),
                    line_frag(east(x,y), cell_pt(x,y,0.0,12.0)),
                ]
            } else { vec![Frag::TextChar(c)] }
        }
        '^' => {
            let has_s = in_set(ctx.s(x,y), NORTH_PORT);
            let has_n = in_set(ctx.n(x,y), SOUTH_PORT);
            if has_s {
                vec![Frag::Polygon(vec![cell_pt(x,y,0.0,12.0), north(x,y), cell_pt(x,y,8.0,12.0)])]
            } else if has_n {
                vec![
                    line_frag(north(x,y), sw(x,y)),
                    line_frag(north(x,y), se(x,y)),
                ]
            } else if ctx.sw(x,y)==Some('/') || ctx.sw(x,y)==Some('X') {
                // diagonal arrow SW (points observed relative)
                vec![Frag::Polygon(vec![cell_pt(x,y,-1.0,12.0), cell_pt(x,y,6.0,4.0), cell_pt(x,y,6.0,15.0)])]
            } else if ctx.se(x,y)==Some('\\') || ctx.se(x,y)==Some('X') {
                vec![Frag::Polygon(vec![cell_pt(x,y,9.0,12.0), cell_pt(x,y,2.0,4.0), cell_pt(x,y,2.0,15.0)])]
            } else { vec![Frag::TextChar(c)] }
        }
        'v' | 'V' => {
            let has_n = in_set(ctx.n(x,y), SOUTH_PORT);
            let has_s = in_set(ctx.s(x,y), NORTH_PORT);
            if has_n {
                vec![Frag::Polygon(vec![cell_pt(x,y,0.0,4.0), cell_pt(x,y,8.0,4.0), south(x,y)])]
            } else if has_s {
                vec![
                    line_frag(nw(x,y), south(x,y)),
                    line_frag(ne(x,y), south(x,y)),
                ]
            } else if matches!(ctx.ne(x,y), Some('/')|Some('X')|Some('.')) {
                vec![Frag::Polygon(vec![cell_pt(x,y,9.0,4.0), cell_pt(x,y,2.0,12.0), cell_pt(x,y,2.0,1.0)])]
            } else if matches!(ctx.nw(x,y), Some('\\')|Some('X')|Some('.')) {
                vec![Frag::Polygon(vec![cell_pt(x,y,-1.0,4.0), cell_pt(x,y,6.0,12.0), cell_pt(x,y,6.0,1.0)])]
            } else { vec![Frag::TextChar(c)] }
        }
        'o' | 'O' => {
            let marker = Marker::from_char(c).unwrap();
            let mut frags = Vec::new();
            let north_v = in_set(ctx.n(x,y), "!:|");
            let south_v = in_set(ctx.s(x,y), "!:|");
            let west_dash = in_set(ctx.w(x,y), "-~");
            let east_dash = in_set(ctx.e(x,y), "-~");
            let nw_diag_primary = ctx.nw(x,y)==Some('\\');
            let ne_diag_primary = ctx.ne(x,y)==Some('/');
            let north_pipe = ctx.n(x,y)==Some('|');
            let mut represented = west_dash || east_dash || north_pipe || nw_diag_primary || ne_diag_primary;
            if matches!(ctx.n(x,y), Some(':')|Some('!')) {
                frags.push(marked_line(north(x,y), center(x,y), marker));
                represented = true;
            }
            if south_v {
                if represented {
                    frags.push(line_frag(sf(x,y), south(x,y)));
                } else {
                    frags.push(marked_line(sf(x,y), center(x,y), marker));
                    represented = true;
                }
            }
            if ctx.sw(x,y)==Some('/') {
                if represented {
                    frags.push(line_frag(swf(x,y), sw(x,y)));
                } else {
                    frags.push(marked_line(swf(x,y), center(x,y), marker));
                    represented = true;
                }
            }
            if ctx.se(x,y)==Some('\\') {
                if represented {
                    frags.push(line_frag(sef(x,y), se(x,y)));
                } else {
                    frags.push(marked_line(sef(x,y), center(x,y), marker));
                    represented = true;
                }
            }
            // "o-o" fallback circle for east marker whose dash was used for west marker
            if frags.is_empty() && in_set(ctx.w(x,y),"-~") {
                let beyond = g.get(x-2,y);
                if beyond==Some('o') || beyond==Some('O') {
                    let r = if c=='o' {3.0} else {4.0};
                    frags.push(Frag::Circle(center(x,y), r));
                }
            }
            if frags.is_empty() && !represented { vec![Frag::TextChar(c)] } else { frags }
        }
        '*' => {
            let marker = Marker::FilledCircle;
            let mut frags: Vec<Frag> = Vec::new();
            let west_dash = in_set(ctx.w(x,y), "-~");
            let east_dash = in_set(ctx.e(x,y), "-~");
            let north_v = in_set(ctx.n(x,y), "!:|");
            let south_v = in_set(ctx.s(x,y), "!:|");
            let north_pipe = ctx.n(x,y)==Some('|');
            let nw_diag_primary = ctx.nw(x,y)==Some('\\');
            let ne_diag_primary = ctx.ne(x,y)==Some('/');
            // represented by a north pipe or diagonal primary (dash west also, unless beyond is o/O)
            let beyond_west = g.get(x-2,y);
            let dash_will_mark = west_dash && beyond_west!=Some('o') && beyond_west!=Some('O');
            let mut represented = north_pipe || nw_diag_primary || ne_diag_primary || dash_will_mark;
            // horizontal
            if west_dash && east_dash {
                frags.push(line_frag(west(x,y), east(x,y)));
            } else if west_dash {
                if beyond_west==Some('o') || beyond_west==Some('O') {
                    frags.push(marked_line(west(x,y), center(x,y), marker));
                    represented = true;
                } else {
                    frags.push(line_frag(west(x,y), center(x,y)));
                }
            } else if east_dash {
                if represented {
                    frags.push(line_frag(center(x,y), east(x,y)));
                } else {
                    frags.push(marked_line(center(x,y), center(x,y), marker));
                    represented = true;
                }
            } else {
                // horizontal junction neighbors
                let jw = in_set(ctx.w(x,y), "oO#*+");
                let je = in_set(ctx.e(x,y), "oO#*+");
                if jw || je {
                    let a = if jw {west(x,y)} else {center(x,y)};
                    let b = if je {east(x,y)} else {center(x,y)};
                    frags.push(line_frag(a,b));
                }
            }
            // north stub for ':'/'!'
            if matches!(ctx.n(x,y), Some(':')|Some('!')) {
                frags.push(marked_line(north(x,y), center(x,y), marker));
                represented = true;
            }
            if south_v {
                if represented {
                    frags.push(line_frag(sf(x,y), south(x,y)));
                } else {
                    frags.push(marked_line(sf(x,y), center(x,y), marker));
                    represented = true;
                }
            }
            if ctx.sw(x,y)==Some('/') {
                if represented { frags.push(line_frag(swf(x,y), sw(x,y))); }
                else { frags.push(marked_line(swf(x,y), center(x,y), marker)); represented=true; }
            }
            if ctx.se(x,y)==Some('\\') {
                if represented { frags.push(line_frag(sef(x,y), se(x,y))); }
                else { frags.push(marked_line(sef(x,y), center(x,y), marker)); represented=true; }
            }
            let _ = north_v;
            if frags.is_empty() && !represented { vec![Frag::TextChar(c)] } else { frags }
        }
        '#' => {
            let has_e = in_set(ctx.e(x,y), "oO#*+-~");
            let has_w = in_set(ctx.w(x,y), "oO#*+-~");
            let has_s = in_set(ctx.s(x,y), NORTH_PORT);
            let has_n = in_set(ctx.n(x,y), SOUTH_PORT);
            let nw_d = matches!(ctx.nw(x,y), Some('\\')|Some('X'));
            let ne_d = matches!(ctx.ne(x,y), Some('/')|Some('X'));
            let sw_d = matches!(ctx.sw(x,y), Some('/')|Some('X'));
            let se_d = matches!(ctx.se(x,y), Some('\\')|Some('X'));
            if has_e||has_w||has_s||has_n {
                let mut frags = vec![Frag::Rect(x as f32*8.0, y as f32*16.0+4.0, 8.0,8.0,true,0.0)];
                if has_n { frags.push(line_frag(north(x,y), nf(x,y))); }
                if has_s { frags.push(line_frag(sf(x,y), south(x,y))); }
                return frags;
            }
            if nw_d||ne_d||sw_d||se_d {
                let cx = x as f32*8.0+4.0; let cy = y as f32*16.0+8.0;
                let pts = vec![Pt::new(cx+2.8,cy+4.0), Pt::new(cx+2.8,cy-4.0), Pt::new(cx-2.8,cy-4.0), Pt::new(cx-2.8,cy+4.0)];
                let mut frags = vec![Frag::Polygon(pts)];
                if nw_d { frags.push(line_frag(nw(x,y), nwf(x,y))); }
                if ne_d { frags.push(line_frag(ne(x,y), nef(x,y))); }
                if sw_d { frags.push(line_frag(swf(x,y), sw(x,y))); }
                if se_d { frags.push(line_frag(sef(x,y), se(x,y))); }
                return frags;
            }
            vec![Frag::TextChar(c)]
        }
        _ => vec![Frag::TextChar(c)],
    }
}

// Enhancement pattern detection for circles/quadrants
struct PatternArc {
    shape: ShapeKind,
    used: Vec<(i32,i32)>,
    anchor: (i32,i32),
}

fn pattern_blocked(g:&Grid, used:&BTreeSet<(i32,i32)>, blockers:&[(i32,i32)]) -> bool {
    blockers.iter().any(|&(x,y)| !is_blank(g,used,x,y))
}

fn try_patterns(g:&Grid, used_in:&BTreeSet<(i32,i32)>, seq_start: usize) -> (Vec<Shape>, BTreeSet<(i32,i32)>) {
    let mut used = used_in.clone();
    let mut shapes: Vec<Shape> = Vec::new();
    let mut seq = seq_start;
    let cells = g.sorted_cells();
    // Semicircle patterns first, scanning origin by sorted cells positions.
    // We'll scan all possible origins in grid range row-major.
    #[derive(Clone,Copy)]
    struct Semi { dxys: &'static [(i32,i32,char)], arc_a:(f32,f32), arc_b:(f32,f32), r:f32, sweep:bool }
    // Coordinates in absolute pixels relative to origin cell (ox*8, oy*16)
    let semis: Vec<Semi> = vec![
        // top r20: origin at '(' cell? origin = top-left of bbox (x of '(' , y of top row)
        Semi{dxys:&[(1,0,'.'),(2,0,'-'),(3,0,'-'),(4,0,'.'),(0,1,'('),(5,1,')')], arc_a:(4.0,24.0), arc_b:(44.0,24.0), r:20.0, sweep:true},
        // top r16
        Semi{dxys:&[(1,0,','),(2,0,'-'),(3,0,'.'),(0,1,'('),(4,1,')')], arc_a:(4.0,24.0), arc_b:(36.0,24.0), r:16.0, sweep:true},
        // bottom r20
        Semi{dxys:&[(0,0,'('),(5,0,')'),(1,1,'`'),(2,1,'-'),(3,1,'-'),(4,1,'\'')], arc_a:(4.0,8.0), arc_b:(44.0,8.0), r:20.0, sweep:false},
        // bottom r16
        Semi{dxys:&[(0,0,'('),(4,0,')'),(1,1,'`'),(2,1,'-'),(3,1,'\'')], arc_a:(4.0,8.0), arc_b:(36.0,8.0), r:16.0, sweep:false},
    ];
    for oy in -1..g.height+1 {
        for ox in -1..g.width+1 {
            for semi in &semis {
                let ok = semi.dxys.iter().all(|&(dx,dy,ch)| g.get(ox+dx,oy+dy)==Some(ch));
                if !ok { continue; }
                // If the anchor constituent cells are all already used by a previous semicircle sharing parens, still allow if top/bottom complementary?
                // Determine used constituents: for top/bottom they share only '(' and ')' between a pair. Allow if at least the non-paren cells are unused.
                let nonparen_unused = semi.dxys.iter().filter(|&&(_,_,ch)| ch!='(' && ch!=')').all(|&(dx,dy,_)| !used.contains(&(ox+dx,oy+dy)));
                if !nonparen_unused { continue; }
                // blockers: row above pattern bbox and column left, adjacent to top/left constituents.
                // Compute blockers generically: cells outside bbox in row oy-1 with x adjacent(+-1) to a top-row constituent,
                // or col ox-1 with y adjacent to a left-column constituent.
                let minx = semi.dxys.iter().map(|d|d.0).min().unwrap();
                let maxx = semi.dxys.iter().map(|d|d.0).max().unwrap();
                let miny = semi.dxys.iter().map(|d|d.1).min().unwrap();
                let maxy = semi.dxys.iter().map(|d|d.1).max().unwrap();
                let mut blockers: Vec<(i32,i32)> = Vec::new();
                for &(dx,dy,_) in semi.dxys {
                    if dy==miny {
                        for bx in (ox+dx-1)..=(ox+dx+1) { blockers.push((bx,oy+miny-1)); }
                    }
                    if dx==minx {
                        for by in (oy+dy-1)..=(oy+dy+1) { blockers.push((ox+minx-1,by)); }
                    }
                }
                let _ = (maxx,maxy);
                if pattern_blocked(g,&used,&blockers) { continue; }
                let a = Pt::new(ox as f32*8.0+semi.arc_a.0, oy as f32*16.0+semi.arc_a.1);
                let b = Pt::new(ox as f32*8.0+semi.arc_b.0, oy as f32*16.0+semi.arc_b.1);
                shapes.push(Shape::new(ShapeKind::Arc{a,b,r:semi.r,large:false,sweep:semi.sweep}, seq, (oy,ox)));
                seq+=1;
                for &(dx,dy,_) in semi.dxys { used.insert((ox+dx,oy+dy)); }
            }
        }
    }
    // Quadrant patterns, generator cells in scan order
    for &(x,y,c) in &cells {
        if used.contains(&(x,y)) { continue; }
        match c {
            '.' | ',' => {
                // NW if '(' SW and '-' E ; NE if '.' and ')' SE and '-' W
                if g.get(x+1,y)==Some('-') && g.get(x-1,y+1)==Some('(') {
                    // blockers rel bbox origin (x-1,y)
                    let blockers = [(x-1,y-1),(x,y-1),(x+1,y-1),(x+2,y-1),(x-2,y),(x-2,y+1),(x-2,y+2)];
                    if !pattern_blocked(g,&used,&blockers) {
                        let (a,r) = if c==',' { (center(x+1,y),16.0) } else { (Pt::new((x+2) as f32*8.0, y as f32*16.0+4.0),20.0) };
                        let b = center(x-1,y+1);
                        shapes.push(Shape::new(ShapeKind::Arc{a,b,r,large:false,sweep:false}, seq, (y,x))); seq+=1;
                        used.insert((x,y)); used.insert((x+1,y)); used.insert((x-1,y+1));
                        continue;
                    }
                }
                if c=='.' && g.get(x-1,y)==Some('-') && g.get(x+1,y+1)==Some(')') {
                    let blockers = [(x-2,y-1),(x-1,y-1),(x,y-1),(x+1,y-1),(x-2,y),(x-2,y+1)];
                    if !pattern_blocked(g,&used,&blockers) {
                        let beyond = (x-2,y);
                        let beyond_ch = g.get(beyond.0,beyond.1);
                        let beyond_used = used.contains(&beyond);
                        let variant = if beyond_ch==Some(',')||beyond_ch==Some('.') { Some(16.0) }
                                      else if beyond_ch.is_none() || beyond_used { Some(20.0) } else { None };
                        if let Some(r) = variant {
                            let a = if r==16.0 { center(x-1,y) } else { Pt::new((x-1) as f32*8.0, y as f32*16.0+4.0) };
                            let b = center(x+1,y+1);
                            shapes.push(Shape::new(ShapeKind::Arc{a,b,r,large:false,sweep:true}, seq, (y,x))); seq+=1;
                            used.insert((x,y)); used.insert((x-1,y)); used.insert((x+1,y+1));
                            continue;
                        }
                    }
                }
            }
            '`' => {
                if g.get(x-1,y-1)==Some('(') && g.get(x+1,y)==Some('-') {
                    let blockers = [(x-2,y-2),(x-1,y-2),(x,y-2),(x-2,y-1),(x-2,y)];
                    if !pattern_blocked(g,&used,&blockers) {
                        let north2 = g.get(x,y-2);
                        let (b,r) = if north2==Some(',') { (center(x+1,y),16.0) } else { (Pt::new((x+2) as f32*8.0, y as f32*16.0+12.0),20.0) };
                        let a = center(x-1,y-1);
                        shapes.push(Shape::new(ShapeKind::Arc{a,b,r,large:false,sweep:false}, seq, (y,x))); seq+=1;
                        used.insert((x,y)); used.insert((x+1,y)); used.insert((x-1,y-1));
                        continue;
                    }
                }
            }
            '\'' => {
                if g.get(x+1,y-1)==Some(')') && g.get(x-1,y)==Some('-') {
                    let blockers = [(x,y-2),(x+1,y-2),(x+2,y-2),(x-2,y-1),(x-2,y),(x-2,y+1)];
                    if !pattern_blocked(g,&used,&blockers) {
                        let north2 = g.get(x,y-2);
                        let north2_used = used.contains(&(x,y-2));
                        let (b,r) = if north2==Some('.') && north2_used { (center(x-1,y),16.0) } else { (Pt::new((x-1) as f32*8.0, y as f32*16.0+12.0),20.0) };
                        let a = center(x+1,y-1);
                        shapes.push(Shape::new(ShapeKind::Arc{a,b,r,large:false,sweep:true}, seq, (y,x))); seq+=1;
                        used.insert((x,y)); used.insert((x-1,y)); used.insert((x+1,y-1));
                        continue;
                    }
                }
            }
            _=>{}
        }
    }
    // "()" small circle patterns: two rounds, snapshot blockers each round.
    for _round in 0..2 {
        let mut matches: Vec<(i32,i32)> = Vec::new();
        for &(x,y,c) in &cells {
            if c!='(' { continue; }
            if used.contains(&(x,y)) || used.contains(&(x+1,y)) { continue; }
            if g.get(x+1,y)!=Some(')') { continue; }
            let blockers = [(x-1,y-1),(x,y-1),(x+1,y-1),(x+2,y-1),(x-1,y),(x-1,y+1)];
            if pattern_blocked(g,&used,&blockers) { continue; }
            matches.push((x,y));
        }
        if matches.is_empty() { break; }
        for (x,y) in matches {
            let cpt = Pt::new(x as f32*8.0+8.0, y as f32*16.0+8.0);
            let mut sh = Shape::new(ShapeKind::Circle{c:cpt,r:4.0}, seq, (y,x)); seq+=1;
            sh.promoted = true;
            shapes.push(sh);
            used.insert((x,y)); used.insert((x+1,y));
        }
    }
    (shapes, used)
}

fn collinear(a:Pt,b:Pt,c:Pt) -> bool {
    let v1x=b.x-a.x; let v1y=b.y-a.y; let v2x=c.x-a.x; let v2y=c.y-a.y;
    (v1x*v2y - v1y*v2x).abs() < 0.001
}
fn try_merge_line(shapes:&mut Vec<Shape>, a:Pt,b:Pt,style:LineStyle,marker_end:Option<Marker>, seq:usize,pos:(i32,i32)) {
    // iterate to allow chain merges
    let mut cur_a=a; let mut cur_b=b; let mut cur_style=style; let mut cur_marker=marker_end; let mut cur_marker_start: Option<Marker>=None;
    let mut merged_into: Option<usize> = None;
    // We try repeatedly to merge cur into an existing line or absorb existing lines into a chosen host.
    // Simpler: first find host by append/prepend rule.
    for i in 0..shapes.len() {
        if let ShapeKind::Line{a:ea,b:eb,style:es,marker_start:ems,marker_end:eme} = shapes[i].kind.clone() {
            if !collinear(ea,eb,cur_a) || !collinear(ea,eb,cur_b) {
                // zero-length existing line: collinear check with ea==eb gives cross 0 always; handle specially
                if !(pt_eq(ea,eb) && pt_eq(ea,cur_a)) { continue; }
            }
            if pt_eq(eb,cur_a) {
                // append cur to host
                let new_style = if es==LineStyle::Broken||cur_style==LineStyle::Broken {LineStyle::Broken} else {LineStyle::Solid};
                let new_marker = cur_marker.or(eme);
                shapes[i].kind = ShapeKind::Line{a:ea,b:cur_b,style:new_style,marker_start:ems,marker_end:new_marker};
                merged_into=Some(i);
                break;
            } else if pt_eq(ea,cur_b) {
                let new_style = if es==LineStyle::Broken||cur_style==LineStyle::Broken {LineStyle::Broken} else {LineStyle::Solid};
                // cur marker_end is at junction ea; if cur had a marker, it would be at start of host
                let new_start = cur_marker.or(ems);
                shapes[i].kind = ShapeKind::Line{a:cur_a,b:eb,style:new_style,marker_start:new_start,marker_end:eme};
                merged_into=Some(i);
                break;
            }
        }
    }
    if let Some(host) = merged_into {
        // Try to absorb other lines that now connect (append/prepend) repeatedly.
        loop {
            let (ha,hb,hstyle,hms,hme) = if let ShapeKind::Line{a,b,style,marker_start,marker_end} = shapes[host].kind.clone() {(a,b,style,marker_start,marker_end)} else {break};
            let mut absorbed=None;
            for i in 0..shapes.len() {
                if i==host {continue;}
                if let ShapeKind::Line{a:ea,b:eb,style:es,marker_start:ems,marker_end:eme} = shapes[i].kind.clone() {
                    if !collinear(ha,hb,ea) || !collinear(ha,hb,eb) { if !(pt_eq(ha,hb)&&pt_eq(ha,ea)) {continue;} }
                    if pt_eq(hb,ea) {
                        let ns = if hstyle==LineStyle::Broken||es==LineStyle::Broken {LineStyle::Broken} else {LineStyle::Solid};
                        shapes[host].kind=ShapeKind::Line{a:ha,b:eb,style:ns,marker_start:hms,marker_end:eme.or(hme)};
                        absorbed=Some(i); break;
                    } else if pt_eq(ha,eb) {
                        let ns = if hstyle==LineStyle::Broken||es==LineStyle::Broken {LineStyle::Broken} else {LineStyle::Solid};
                        shapes[host].kind=ShapeKind::Line{a:ea,b:hb,style:ns,marker_start:ems.or(hms),marker_end:hme};
                        absorbed=Some(i); break;
                    }
                }
            }
            if let Some(idx)=absorbed { shapes.remove(idx); } else { break; }
            // host index may shift if removed before it
            // Re-find host by seq? seq of host shape is unique originally; simpler: break after one absorb due complexity (rare)
            break;
        }
        return;
    }
    let _ = cur_marker_start;
    shapes.push(Shape::new(ShapeKind::Line{a:cur_a,b:cur_b,style:cur_style,marker_start:None,marker_end:cur_marker}, seq,pos));
}

fn add_frag(shapes:&mut Vec<Shape>, frag:Frag, cellx:i32,celly:i32, seq:&mut usize) {
    let pos=(celly,cellx);
    match frag {
        Frag::Nothing=>{},
        Frag::Line(a,b,style,m)=>{ try_merge_line(shapes,a,b,style,m,*seq,pos); *seq+=1; }
        Frag::Arc(a,b,r,large,sweep)=>{ shapes.push(Shape::new(ShapeKind::Arc{a,b,r,large,sweep},*seq,pos)); *seq+=1; }
        Frag::Circle(c,r)=>{ shapes.push(Shape::new(ShapeKind::Circle{c,r},*seq,pos)); *seq+=1; }
        Frag::Rect(x,y,w,h,filled,rx)=>{ shapes.push(Shape::new(ShapeKind::Rect{x,y,w,h,filled,rx},*seq,pos)); *seq+=1; }
        Frag::Polygon(pts)=>{ shapes.push(Shape::new(ShapeKind::Polygon{pts},*seq,pos)); *seq+=1; }
        Frag::TextChar(ch)=>{
            // search existing texts in reverse for expected x
            let mut found=None;
            for (i,sh) in shapes.iter().enumerate().rev() {
                if let ShapeKind::Text{cell_x,cell_y,s} = &sh.kind {
                    if *cell_y==celly && *cell_x + (s.len() as i32) == cellx {
                        found=Some(i); break;
                    }
                }
            }
            if let Some(i)=found {
                if let ShapeKind::Text{s,..} = &mut shapes[i].kind { s.push(ch); }
            } else {
                shapes.push(Shape::new(ShapeKind::Text{cell_x:cellx,cell_y:celly,s:ch.to_string()},*seq,pos));
            }
            *seq+=1;
        }
    }
}

// Arc geometry: compute center from endpoints/radius/sweep/large
fn arc_center(a:Pt,b:Pt,r:f32,large:bool,sweep:bool) -> Option<Pt> {
    let dx=b.x-a.x; let dy=b.y-a.y;
    let d2=dx*dx+dy*dy;
    if d2==0.0 { return None; }
    let d=d2.sqrt();
    let mut rr=r;
    if d>2.0*rr { rr=d/2.0; }
    let mid=Pt::new((a.x+b.x)/2.0,(a.y+b.y)/2.0);
    let h=(rr*rr - d2/4.0).max(0.0).sqrt();
    // unit perpendicular
    let ux=-dy/d; let uy=dx/d;
    let c1=Pt::new(mid.x+h*ux, mid.y+h*uy);
    let c2=Pt::new(mid.x-h*ux, mid.y-h*uy);
    // choose based on sweep/large: compute angular travel for each candidate
    let pick = |c:Pt| -> bool {
        // return true if candidate matches flags
        let ang = arc_angle(a,b,c,sweep);
        let is_large = ang>180.0;
        is_large==large || (ang-180.0).abs()<0.001
    };
    // If h==0 both same
    if h<0.0001 { return Some(mid); }
    // Determine which center gives an arc on correct side: For minor arc, test midpoint direction etc.
    // Use flag logic: For a given center, moving from a to b in sweep direction (sweep=true is clockwise in SVG y-down coords i.e. angle increasing)
    // angle calc below uses atan2 in y-down plane.
    if pick(c1) && !pick(c2) { Some(c1) } else if pick(c2) { Some(c2) } else { Some(c1) }
}
fn angle_of(p:Pt,c:Pt)->f32{ (p.y-c.y).atan2(p.x-c.x).to_degrees() }
fn arc_angle(a:Pt,b:Pt,c:Pt,sweep:bool)->f32{
    let a1=angle_of(a,c); let a2=angle_of(b,c);
    let mut diff = a2-a1;
    if sweep {
        // clockwise in y-down: angle increasing
        while diff<=0.0 { diff+=360.0; }
        if diff>=360.0 { diff-=360.0; }
        // atan2 returns -180..180, diff in -360..360; normalize to (0,360]
        if diff==0.0 { diff=360.0; }
        diff
    } else {
        while diff>=0.0 { diff-=360.0; }
        if diff<=-360.0 { diff+=360.0; }
        if diff==0.0 { diff=-360.0; }
        -diff
    }
}

fn merge_arcs(shapes:&mut Vec<Shape>) {
    loop {
        let mut found: Option<(usize,usize,ShapeKind,bool)> = None; // i,j,newkind,is_circle
        'outer: for i in 0..shapes.len() {
            let (ia,ib,ir,ilarge,isweep) = if let ShapeKind::Arc{a,b,r,large,sweep}=shapes[i].kind.clone(){(a,b,r,large,sweep)}else{continue};
            let ic = match arc_center(ia,ib,ir,ilarge,isweep){Some(c)=>c,None=>continue};
            for j in 0..shapes.len() {
                if j==i {continue;}
                let (ja,jb,jr,jlarge,jsweep) = if let ShapeKind::Arc{a,b,r,large,sweep}=shapes[j].kind.clone(){(a,b,r,large,sweep)}else{continue};
                if (ir-jr).abs()>0.001 {continue;}
                let jc = match arc_center(ja,jb,jr,jlarge,jsweep){Some(c)=>c,None=>continue};
                if !pt_eq(ic,jc) {continue;}
                // Try orient j to continue i, or i to continue j. We'll construct merged in i's sweep direction if possible.
                // Cases:
                let iang = arc_angle(ia,ib,ic,isweep);
                // j oriented in same sweep direction: its natural start/end if jsweep==isweep, else reversed start/end
                let (ja_o,jb_o,jang) = if jsweep==isweep { (ja,jb,arc_angle(ja,jb,jc,jsweep)) } else { (jb,ja,arc_angle(jb,ja,jc,isweep)) };
                let mut merged: Option<(Pt,Pt,f32)> = None;
                if pt_eq(ib,ja_o) {
                    merged=Some((ia,jb_o,iang+jang));
                } else if pt_eq(jb_o,ia) {
                    merged=Some((ja_o,ib,iang+jang));
                }
                if let Some((na,nb,total))=merged {
                    if total>=359.9 {
                        found=Some((i,j,ShapeKind::Circle{c:ic,r:ir},true));
                    } else {
                        found=Some((i,j,ShapeKind::Arc{a:na,b:nb,r:ir,large:total>180.0,sweep:isweep},false));
                    }
                    break 'outer;
                }
            }
        }
        if let Some((i,j,newkind,is_circle))=found {
            let pos = std::cmp::min(shapes[i].pos, shapes[j].pos);
            let seqv = std::cmp::min(shapes[i].seq, shapes[j].seq);
            // remove j first (higher index handling)
            let (lo,hi) = if i<j {(i,j)} else {(j,i)};
            shapes.remove(hi);
            shapes.remove(lo);
            let mut sh = Shape::new(newkind, seqv, pos);
            if is_circle { sh.promoted=true; }
            // insert at lo position to preserve order
            let insert_at = lo.min(shapes.len());
            shapes.insert(insert_at, sh);
        } else { break; }
    }
}

fn normalize_line(a:Pt,b:Pt)->(Pt,Pt){
    // return in a canonical order for interval checks (by x then y)
    if a.x<b.x || ((a.x-b.x).abs()<0.001 && a.y<=b.y) {(a,b)} else {(b,a)}
}

fn promote_rects(shapes:&mut Vec<Shape>) {
    loop {
        // collect line indices
        #[derive(Clone)]
        struct LInfo{idx:usize,a:Pt,b:Pt}
        let mut horiz:Vec<LInfo>=Vec::new();
        let mut vert:Vec<LInfo>=Vec::new();
        for (idx,sh) in shapes.iter().enumerate() {
            if let ShapeKind::Line{a,b,..}=sh.kind {
                let (na,nb)=normalize_line(a,b);
                if (na.y-nb.y).abs()<0.001 && (na.x-nb.x).abs()>0.001 { horiz.push(LInfo{idx,a:na,b:nb}); }
                else if (na.x-nb.x).abs()<0.001 && (na.y-nb.y).abs()>0.001 { vert.push(LInfo{idx,a:na,b:nb}); }
            }
        }
        let mut found: Option<(Vec<usize>, ShapeKind,(i32,i32),usize)> = None;
        // sharp rects first? Try all combos for sharp, then rounded.
        'search: for hi1 in 0..horiz.len() {
            for hi2 in 0..horiz.len() {
                if hi1==hi2{continue;}
                let top=&horiz[hi1]; let bot=&horiz[hi2];
                if !(top.a.y<bot.a.y) {continue;}
                if !((top.a.x-bot.a.x).abs()<0.001 && (top.b.x-bot.b.x).abs()<0.001) {continue;}
                let x1=top.a.x; let x2=top.b.x; let y1=top.a.y; let y2=bot.a.y;
                for vi1 in 0..vert.len() {
                    for vi2 in 0..vert.len() {
                        if vi1==vi2{continue;}
                        let left=&vert[vi1]; let right=&vert[vi2];
                        if !((left.a.x-x1).abs()<0.001 && (right.a.x-x2).abs()<0.001) {continue;}
                        if !((left.a.y-y1).abs()<0.001 && (left.b.y-y2).abs()<0.001 && (right.a.y-y1).abs()<0.001 && (right.b.y-y2).abs()<0.001){continue;}
                        let idxs=vec![top.idx,bot.idx,left.idx,right.idx];
                        let pos=idxs.iter().map(|&i|shapes[i].pos).min().unwrap();
                        let seqv=idxs.iter().map(|&i|shapes[i].seq).min().unwrap();
                        found=Some((idxs,ShapeKind::Rect{x:x1,y:y1,w:x2-x1,h:y2-y1,filled:false,rx:0.0},pos,seqv));
                        break 'search;
                    }
                }
            }
        }
        if found.is_none() {
            // rounded rect: lines with arcs connecting corners, all arcs same radius
            // collect arcs
            #[derive(Clone)] struct AInfo{idx:usize,a:Pt,b:Pt,r:f32}
            let mut arcs:Vec<AInfo>=Vec::new();
            for (idx,sh) in shapes.iter().enumerate() {
                if let ShapeKind::Arc{a,b,r,..}=sh.kind { arcs.push(AInfo{idx,a,b,r}); }
            }
            let find_arc = |p:Pt,q:Pt,arcs:&Vec<AInfo>| -> Option<AInfo> {
                arcs.iter().find(|ai| (pt_eq(ai.a,p)&&pt_eq(ai.b,q))||(pt_eq(ai.a,q)&&pt_eq(ai.b,p))).cloned()
            };
            'rsearch: for hi1 in 0..horiz.len() {
                for hi2 in 0..horiz.len() {
                    if hi1==hi2{continue;}
                    let top=&horiz[hi1]; let bot=&horiz[hi2];
                    if !(top.a.y<bot.a.y){continue;}
                    if !((top.a.x-bot.a.x).abs()<0.001 && (top.b.x-bot.b.x).abs()<0.001){continue;}
                    let y1=top.a.y; let y2=bot.a.y;
                    for vi1 in 0..vert.len() {
                        for vi2 in 0..vert.len() {
                            if vi1==vi2{continue;}
                            let left=&vert[vi1]; let right=&vert[vi2];
                            if !(left.a.x < top.a.x && right.a.x > top.b.x) { continue; }
                            // vertical intervals should match each other
                            if !((left.a.y-right.a.y).abs()<0.001 && (left.b.y-right.b.y).abs()<0.001){continue;}
                            if !(left.a.y>y1 && left.b.y<y2){continue;}
                            let tl=find_arc(top.a,left.a,&arcs);
                            let tr=find_arc(top.b,right.a,&arcs);
                            let bl=find_arc(bot.a,left.b,&arcs);
                            let br=find_arc(bot.b,right.b,&arcs);
                            if let (Some(tl),Some(tr),Some(bl),Some(br))=(tl,tr,bl,br){
                                if !((tl.r-tr.r).abs()<0.001&&(tl.r-bl.r).abs()<0.001&&(tl.r-br.r).abs()<0.001){continue;}
                                let x1=left.a.x; let x2=right.a.x;
                                let idxs=vec![top.idx,bot.idx,left.idx,right.idx,tl.idx,tr.idx,bl.idx,br.idx];
                                let pos=idxs.iter().map(|&i|shapes[i].pos).min().unwrap();
                                let seqv=idxs.iter().map(|&i|shapes[i].seq).min().unwrap();
                                found=Some((idxs,ShapeKind::Rect{x:x1,y:y1,w:x2-x1,h:y2-y1,filled:false,rx:tl.r},pos,seqv));
                                break 'rsearch;
                            }
                        }
                    }
                }
            }
        }
        if let Some((mut idxs,kind,pos,seqv))=found {
            idxs.sort_unstable(); idxs.dedup();
            for &idx in idxs.iter().rev() { shapes.remove(idx); }
            let mut sh=Shape::new(kind,seqv,pos); sh.promoted=true;
            shapes.push(sh);
        } else { break; }
    }
}

fn point_on_segment(p:Pt,a:Pt,b:Pt)->bool{
    if !collinear(a,b,p){return false;}
    let minx=a.x.min(b.x)-0.001; let maxx=a.x.max(b.x)+0.001;
    let miny=a.y.min(b.y)-0.001; let maxy=a.y.max(b.y)+0.001;
    p.x>=minx&&p.x<=maxx&&p.y>=miny&&p.y<=maxy
}
fn shape_endpoints(sh:&Shape)->Vec<Pt>{
    match &sh.kind {
        ShapeKind::Line{a,b,..}=>vec![*a,*b],
        ShapeKind::Arc{a,b,..}=>vec![*a,*b],
        _=>Vec::new(),
    }
}
fn connected(a:&Shape,b:&Shape)->bool{
    // Text-Text
    if let (ShapeKind::Text{cell_x:ax,cell_y:ay,s:as_}, ShapeKind::Text{cell_x:bx,cell_y:by,s:bs}) = (&a.kind,&b.kind) {
        if ay!=by {return false;}
        let a_end=ax+as_.chars().count() as i32;
        let b_end=bx+bs.chars().count() as i32;
        return *ax<=b_end && *bx<=a_end;
    }
    // Only Line/Arc connect
    let a_is = matches!(a.kind, ShapeKind::Line{..}|ShapeKind::Arc{..});
    let b_is = matches!(b.kind, ShapeKind::Line{..}|ShapeKind::Arc{..});
    if !a_is||!b_is{return false;}
    let aeps=shape_endpoints(a); let beps=shape_endpoints(b);
    for &p in &aeps {
        for &q in &beps { if pt_eq(p,q){return true;} }
        if let ShapeKind::Line{a:la,b:lb,..}=b.kind { if point_on_segment(p,la,lb){return true;} }
    }
    for &p in &beps {
        if let ShapeKind::Line{a:la,b:lb,..}=a.kind { if point_on_segment(p,la,lb){return true;} }
    }
    false
}

fn group_shapes(shapes:Vec<Shape>) -> Vec<Shape> {
    let n=shapes.len();
    let mut comp_id=vec![usize::MAX;n];
    let mut comps:Vec<Vec<usize>>=Vec::new();
    for i in 0..n {
        if comp_id[i]!=usize::MAX{continue;}
        // BFS
        let mut stack=vec![i]; comp_id[i]=comps.len();
        let mut members=Vec::new();
        while let Some(u)=stack.pop(){
            members.push(u);
            for v in 0..n {
                if comp_id[v]==usize::MAX && connected(&shapes[u],&shapes[v]) {
                    comp_id[v]=comps.len(); stack.push(v);
                }
            }
        }
        members.sort_unstable();
        comps.push(members);
    }
    // Partition: promoted first, then singletons, then groups.
    // But a promoted shape that is in a multi-member component should stay in group? Promoted rects/circles are never connected (connected only checks Line/Arc/Text, Rect/Circle not connected to anything) so they'll be singletons.
    let mut promoted:Vec<Shape>=Vec::new();
    let mut singles:Vec<Shape>=Vec::new();
    let mut groups:Vec<Shape>=Vec::new();
    // Need to move out of shapes by index; clone is easier.
    for members in comps {
        if members.len()==1 {
            let sh=shapes[members[0]].clone();
            if sh.promoted { promoted.push(sh); } else { singles.push(sh); }
        } else {
            // If all members are ... create group
            let pos=members.iter().map(|&i|shapes[i].pos).min().unwrap();
            let seqv=members.iter().map(|&i|shapes[i].seq).min().unwrap();
            let children=members.iter().map(|&i|shapes[i].clone()).collect();
            groups.push(Shape::new(ShapeKind::Group(children),seqv,pos));
        }
    }
    promoted.sort_by_key(|s|s.pos);
    // singles and groups already in comps discovery order which is by first index = seq order as shapes input order preserved.
    let mut out=Vec::new();
    out.extend(promoted); out.extend(singles); out.extend(groups);
    out
}

fn escape_text(s:&str)->String{
    let mut out=String::new();
    for c in s.chars(){
        match c {
            '&'=>out.push_str("&amp;"),
            '<'=>out.push_str("&lt;"),
            '>'=>out.push_str("&gt;"),
            '"'=>out.push_str("&quot;"),
            '\''=>out.push_str("&#39;"),
            _=>out.push(c),
        }
    }
    out
}

struct FmtF(f32);
impl fmt::Display for FmtF{ fn fmt(&self,f:&mut fmt::Formatter)->fmt::Result{ write!(f,"{}",self.0)}}

fn render_shape(sh:&Shape, scale:f32, indent:&str, in_group:bool, out:&mut String){
    let s=|v:f32| FmtF(v*scale);
    match &sh.kind {
        ShapeKind::Line{a,b,style,marker_start,marker_end}=>{
            let mut class = match style {LineStyle::Solid=>"solid".to_string(),LineStyle::Broken=>"broken".to_string()};
            if let Some(m)=marker_start { class.push_str(&format!(" start_marked_{}",m.suffix())); }
            if let Some(m)=marker_end { class.push_str(&format!(" end_marked_{}",m.suffix())); }
            out.push_str(&format!("{}<line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}\"></line>\n",indent,s(a.x),s(a.y),s(b.x),s(b.y),class));
        }
        ShapeKind::Arc{a,b,r,large,sweep}=>{
            out.push_str(&format!("{}<path d=\"M {},{} A {},{} 0,{},{} {},{}\" class=\"nofill\"></path>\n",indent,s(a.x),s(a.y),s(*r),s(*r),if *large{1}else{0},if *sweep{1}else{0},s(b.x),s(b.y)));
        }
        ShapeKind::Circle{c,r}=>{
            out.push_str(&format!("{}<circle cx=\"{}\" cy=\"{}\" r=\"{}\" class=\"nofill\"></circle>\n",indent,s(c.x),s(c.y),s(*r)));
        }
        ShapeKind::Rect{x,y,w,h,filled,rx}=>{
            let class=if *filled {"solid filled"} else {"solid nofill"};
            out.push_str(&format!("{}<rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" class=\"{}\" rx=\"{}\"></rect>\n",indent,s(*x),s(*y),s(*w),s(*h),class,s(*rx)));
        }
        ShapeKind::Polygon{pts}=>{
            let pts_s=pts.iter().map(|p|format!("{},{}",s(p.x),s(p.y))).collect::<Vec<_>>().join(" ");
            out.push_str(&format!("{}<polygon points=\"{}\" class=\"filled\"></polygon>\n",indent,pts_s));
        }
        ShapeKind::Text{cell_x,cell_y,s:txt}=>{
            let tx=*cell_x as f32*8.0+2.0; let ty=*cell_y as f32*16.0+12.0;
            if in_group {
                out.push_str(&format!("{}<text x=\"{}\" y=\"{}\">{}</text>\n",indent,s(tx),s(ty),escape_text(txt)));
            } else {
                out.push_str(&format!("{}<text x=\"{}\" y=\"{}\" >{}</text>\n",indent,s(tx),s(ty),escape_text(txt)));
            }
        }
        ShapeKind::Group(children)=>{
            out.push_str(&format!("{}<g>\n",indent));
            let child_indent=format!("{}  ",indent);
            for ch in children { render_shape(ch,scale,&child_indent,true,out); }
            out.push_str(&format!("{}</g>\n",indent));
        }
    }
}

fn style_text(settings:&Settings)->String{
    let mut t=String::new();
    t.push_str(&format!(".svgbob line, .svgbob path, .svgbob circle, .svgbob rect, .svgbob polygon {{\n  stroke: {};\n  stroke-width: {};\n  stroke-opacity: 1;\n  fill-opacity: 1;\n  stroke-linecap: round;\n  stroke-linejoin: miter;\n}}\n\n",settings.stroke_color, FmtF(settings.stroke_width)));
    t.push_str(&format!(".svgbob text {{\n  white-space: pre;\n  fill: {};\n  font-family: {};\n  font-size: {}px;\n}}\n\n",settings.stroke_color, settings.font_family, settings.font_size));
    t.push_str(&format!(".svgbob rect.backdrop {{\n  stroke: none;\n  fill: {};\n}}\n\n",settings.background));
    t.push_str(".svgbob .broken {\n  stroke-dasharray: 8;\n}\n\n");
    t.push_str(&format!(".svgbob .filled {{\n  fill: {};\n}}\n\n",settings.fill_color));
    t.push_str(&format!(".svgbob .bg_filled {{\n  fill: {};\n  stroke-width: 1;\n}}\n\n",settings.background));
    t.push_str(&format!(".svgbob .nofill {{\n  fill: {};\n}}\n\n",settings.background));
    for name in ["arrow","diamond","circle","open_circle","big_open_circle"] {
        t.push_str(&format!(".svgbob .end_marked_{} {{\n  marker-end: url(#{}}});\n}}\n\n",name,name));
        t.push_str(&format!(".svgbob .start_marked_{} {{\n  marker-start: url(#{}}});\n}}\n\n",name,name));
    }
    t
}

pub fn to_svg(input:&str, settings:&Settings)->String{
    let grid=Grid::parse(input);
    let width_px=(grid.width as f32+1.0)*8.0;
    let height_px=(grid.height as f32+1.0)*16.0;
    // Stage: patterns
    let (pattern_shapes, used) = try_patterns(&grid, &BTreeSet::new(), 0);
    let mut shapes:Vec<Shape>=Vec::new();
    let mut seq:usize=0;
    for sh in pattern_shapes { let mut sh=sh; sh.seq=seq; seq+=1; shapes.push(sh); }
    let ctx=Ctx{g:&grid, used:&used};
    for (x,y,c) in grid.sorted_cells() {
        if used.contains(&(x,y)) { continue; }
        let frags=fragments_for(&ctx,x,y,c);
        for frag in frags { add_frag(&mut shapes,frag,x,y,&mut seq); }
    }
    merge_arcs(&mut shapes);
    promote_rects(&mut shapes);
    let final_shapes=group_shapes(shapes);
    let scale=settings.scale;
    let w=FmtF(width_px*scale); let h=FmtF(height_px*scale);
    let mut out=String::new();
    out.push_str(&format!("<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"{}\" height=\"{}\" class=\"svgbob\">\n",w,h));
    out.push_str("  <style>");
    out.push_str(&style_text(settings));
    out.push_str("</style>\n");
    out.push_str("  <defs>\n");
    out.push_str("    <marker id=\"arrow\" viewBox=\"-2 -2 8 8\" refX=\"4\" refY=\"2\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n      <polygon points=\"0,0 0,4 4,2 0,0\"></polygon>\n    </marker>\n");
    out.push_str("    <marker id=\"diamond\" viewBox=\"-2 -2 8 8\" refX=\"4\" refY=\"2\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n      <polygon points=\"0,2 2,0 4,2 2,4 0,2\"></polygon>\n    </marker>\n");
    out.push_str("    <marker id=\"circle\" viewBox=\"0 0 8 8\" refX=\"4\" refY=\"4\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n      <circle cx=\"4\" cy=\"4\" r=\"2\" class=\"filled\"></circle>\n    </marker>\n");
    out.push_str("    <marker id=\"open_circle\" viewBox=\"0 0 8 8\" refX=\"4\" refY=\"4\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n      <circle cx=\"4\" cy=\"4\" r=\"2\" class=\"bg_filled\"></circle>\n    </marker>\n");
    out.push_str("    <marker id=\"big_open_circle\" viewBox=\"0 0 8 8\" refX=\"4\" refY=\"4\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n      <circle cx=\"4\" cy=\"4\" r=\"3\" class=\"bg_filled\"></circle>\n    </marker>\n");
    out.push_str("  </defs>\n");
    out.push_str(&format!("  <rect class=\"backdrop\" x=\"0\" y=\"0\" width=\"{}\" height=\"{}\"></rect>\n",w,h));
    for sh in &final_shapes { render_shape(sh,scale,"  ",false,&mut out); }
    out.push_str("</svg>");
    out
}
