// Jaro-Winkler
fn jaro(a:&str,b:&str)->f64{
    let a:Vec<char>=a.chars().collect(); let b:Vec<char>=b.chars().collect();
    if a.is_empty() && b.is_empty() {return 1.0;}
    if a.is_empty()||b.is_empty(){return 0.0;}
    let max_dist = (a.len().max(b.len())/2).saturating_sub(1);
    let mut a_match=vec![false;a.len()]; let mut b_match=vec![false;b.len()];
    let mut matches=0usize;
    for i in 0..a.len(){
        let start=i.saturating_sub(max_dist);
        let end=(i+max_dist+1).min(b.len());
        for j in start..end{
            if !b_match[j] && a[i]==b[j]{a_match[i]=true;b_match[j]=true;matches+=1;break;}
        }
    }
    if matches==0{return 0.0;}
    let mut t=0usize; let mut j=0usize;
    for i in 0..a.len(){ if a_match[i]{ while !b_match[j]{j+=1;} if a[i]!=b[j]{t+=1;} j+=1; } }
    let t=t/2;
    let m=matches as f64;
    (m/a.len() as f64 + m/b.len() as f64 + (m - t as f64)/m)/3.0
}
fn jaro_winkler(a:&str,b:&str)->f64{
    let j=jaro(a,b);
    let prefix=a.chars().zip(b.chars()).take(4).take_while(|(x,y)|x==y).count() as f64;
    j + prefix*0.1*(1.0-j)
}
fn did_you_mean<'a>(v:&str, candidates:&[&'a str]) -> Option<&'a str> {
    let mut best:Option<(&str,f64)>=None;
    for &cand in candidates {
        let conf=jaro_winkler(v,cand);
        if conf>0.8 {
            if best.map_or(true,|(_,bc)|conf>bc){best=Some((cand,conf));}
        }
    }
    best.map(|(c,_)|c)
}

fn err_exit(msg:String) -> ! { eprint!("{}",msg); process::exit(1) }
fn usage_from_used(bin:&str, used:&[String], full:&str) -> String {
    if used.is_empty() { format!("{} {}",bin,full) } else { format!("{} {}",bin,used.join(" ")) }
}
fn unknown_argument(bin:&str, display:&str, used:&[String], full:&str, suggestion:Option<(&str,String)>, prefix:&str) -> ! {
    let mut msg=format!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n",display);
    let usage;
    if let Some((sug,canon)) = suggestion {
        if display.starts_with("--") {
            msg.push_str(&format!("\tDid you mean \u{1b}[32m--\u{1b}[0m\u{1b}[32m{}\u{1b}[0m?\n",sug));
        }
        usage=format!("{}{}",prefix,canon);
    } else {
        usage=format!("{}{}",prefix,usage_from_used("",used,full).trim_start().to_string());
        // usage_from_used above with empty bin gives leading space handling; reconstruct simpler:
        // We'll override below.
    }
    let usage_final = if suggestion.is_some() { usage } else {
        if used.is_empty() { format!("{}{}",prefix,full) } else { format!("{}{}",prefix,used.join(" ")) }
    };
    msg.push_str(&format!("\nUSAGE:\n    {}\n\nFor more information try --help\n",usage_final));
    err_exit(msg)
}
fn duplicate_argument(prefix:&str, display:&str) -> ! {
    err_exit(format!("error: The argument '{}' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    {}{}\n\nFor more information try --help\n",display,prefix,display))
}
fn missing_value(prefix:&str, display:&str, used:&[String]) -> ! {
    let usage = if used.is_empty() { format!("{}{}",prefix,display) } else { format!("{}{}",prefix,used.join(" ")) };
    err_exit(format!("error: The argument '{}' requires a value but none was supplied\n\nUSAGE:\n    {}\n\nFor more information try --help\n",display,usage))
}
fn subcommand_error(bin:&str, token:&str, used:&[String]) -> ! {
    let sug = did_you_mean(token.trim_start_matches('-'), &["build","help"]).unwrap_or("help");
    // If token is exactly a subcommand (after -- case), suggestion is itself
    let sug = if token=="build"||token=="help" { token } else { sug };
    let usage = if used.is_empty() { format!("{} [FLAGS] [OPTIONS] [input] [SUBCOMMAND]",bin) } else { format!("{} {}",bin,used.join(" ")) };
    err_exit(format!("error: The subcommand '{}' wasn't recognized\n\tDid you mean '{}'?\n\nIf you believe you received this message in error, try re-running with '{} -- {}'\n\nUSAGE:\n    {}\n\nFor more information try --help\n",token,sug,bin,token,usage))
}

#[derive(Default, Clone)]
struct TopArgs {
    inline: bool,
    input: Option<String>,
    output: Option<String>,
    background: Option<String>,
    fill_color: Option<String>,
    stroke_color: Option<String>,
    font_family: Option<String>,
    font_size: Option<String>,
    stroke_width: Option<String>,
    scale: Option<String>,
    build_input: Option<String>,
    build_outdir: Option<String>,
    is_build: bool,
}

const TOP_LONGS:[&str;10]=["help","version","background","fill-color","font-family","font-size","output","scale","stroke-color","stroke-width"];
const BUILD_LONGS:[&str;4]=["help","version","input","outdir"];

fn canon_top(long:&str)->String{
    match long {
        "help"=>"--help".to_string(),
        "version"=>"--version".to_string(),
        _=>format!("--{} <{}>",long,long),
    }
}
fn canon_build(long:&str)->String{
    match long {"help"=>"--help".to_string(),"version"=>"--version".to_string(),_=>format!("--{} <{}>",long,long)}
}
fn set_top_option(args:&mut TopArgs, long:&str, val:String){
    match long {
        "background"=>args.background=Some(val),
        "fill-color"=>args.fill_color=Some(val),
        "stroke-color"=>args.stroke_color=Some(val),
        "font-family"=>args.font_family=Some(val),
        "font-size"=>args.font_size=Some(val),
        "stroke-width"=>args.stroke_width=Some(val),
        "scale"=>args.scale=Some(val),
        "output"=>args.output=Some(val),
        _=>{}
    }
}
fn top_option_present(args:&TopArgs,long:&str)->bool{
    match long {
        "background"=>args.background.is_some(),
        "fill-color"=>args.fill_color.is_some(),
        "stroke-color"=>args.stroke_color.is_some(),
        "font-family"=>args.font_family.is_some(),
        "font-size"=>args.font_size.is_some(),
        "stroke-width"=>args.stroke_width.is_some(),
        "scale"=>args.scale.is_some(),
        "output"=>args.output.is_some(),
        _=>false,
    }
}
fn is_recognized_flag_token(tok:&str, build:bool)->bool{
    if tok.starts_with("--") {
        let name=tok[2..].split('=').next().unwrap_or("");
        if build { BUILD_LONGS.contains(&name) } else { TOP_LONGS.contains(&name) }
    } else if tok.starts_with('-') && tok.len()>1 {
        let first=tok.chars().nth(1).unwrap();
        if build { matches!(first,'h'|'V'|'i'|'o') } else { matches!(first,'h'|'V'|'s'|'o') }
    } else { false }
}
fn flag_display(tok:&str)->String{
    if tok.starts_with("--") {
        format!("--{}",tok[2..].split('=').next().unwrap_or(""))
    } else if tok.starts_with('-') && tok.len()>1 {
        format!("-{}",tok.chars().nth(1).unwrap())
    } else { tok.to_string() }
}

fn parse_args(bin:&str) -> TopArgs {
    let argv:Vec<String>=env::args().skip(1).collect();
    let mut args=TopArgs::default();
    let mut used:Vec<String>=Vec::new();
    let mut seen_s=false;
    let mut pending_missing:Option<String>=None; // canonical display
    let mut pending_missing_long:Option<String>=None;
    let mut after_dd=false;
    let mut i=0usize;
    // helper closures can't easily capture mut; inline code
    while i<argv.len() {
        let tok=argv[i].clone();
        if args.is_build {
            // build parsing handled in separate loop below by breaking with remaining index
            break;
        }
        if !after_dd && tok=="--" { after_dd=true; i+=1; continue; }
        if !after_dd && tok.starts_with("--") && tok.len()>2 {
            let body=&tok[2..];
            let (name, inline_val) = match body.find('=') {
                Some(eq)=>(body[..eq].to_string(), Some(body[eq+1..].to_string())),
                None=>(body.to_string(),None),
            };
            if name=="help" { print_help(bin); }
            if name=="version" { print_version(); }
            if TOP_LONGS.contains(&name.as_str()) {
                let canon=canon_top(&name);
                if top_option_present(&args,&name) || used.contains(&canon) {
                    duplicate_argument(&format!("{} ",bin), &canon);
                }
                used.push(canon.clone());
                if let Some(v)=inline_val {
                    set_top_option(&mut args,&name,v);
                } else {
                    // lookahead
                    if i+1>=argv.len() {
                        missing_value(&format!("{} ",bin), &canon, &used);
                    }
                    let next=argv[i+1].clone();
                    if next=="--" {
                        missing_value(&format!("{} ",bin), &canon, &used);
                    } else if next.starts_with('-') && next!="-" {
                        if is_recognized_flag_token(&next,false) {
                            // check if it's help/version -> next iteration will exit; just mark pending
                            pending_missing=Some(canon.clone());
                            pending_missing_long=Some(name.clone());
                            // set a placeholder? To detect duplicate, used contains canon. Keep option None.
                            // continue without consuming next
                        } else {
                            let disp=flag_display(&next);
                            unknown_argument(bin,&disp,&used,"[FLAGS] [OPTIONS] [input] [SUBCOMMAND]",None,&format!("{} ",bin));
                        }
                    } else {
                        set_top_option(&mut args,&name,next);
                        i+=1;
                    }
                }
                i+=1; continue;
            } else {
                let disp=format!("--{}",name);
                let sug=did_you_mean(&name,&TOP_LONGS);
                let suggestion=sug.map(|s|(s,canon_top(s)));
                unknown_argument(bin,&disp,&used,"[FLAGS] [OPTIONS] [input] [SUBCOMMAND]",suggestion,&format!("{} ",bin));
            }
        }
        if !after_dd && tok.starts_with('-') && tok.len()>1 && tok!="-" {
            // short cluster
            let chars:Vec<char>=tok.chars().collect();
            let mut j=1usize;
            let mut consumed_next=false;
            while j<chars.len() {
                let ch=chars[j];
                match ch {
                    'h'=>print_help(bin),
                    'V'=>print_version(),
                    's'=>{
                        if seen_s { duplicate_argument(&format!("{} ",bin),"-s"); }
                        seen_s=true; args.inline=true;
                        if !used.contains(&"-s".to_string()){used.push("-s".to_string());}
                        j+=1;
                    }
                    'o'=>{
                        let canon=canon_top("output");
                        if top_option_present(&args,"output") || used.contains(&canon) {
                            duplicate_argument(&format!("{} ",bin),&canon);
                        }
                        used.push(canon.clone());
                        // rest of cluster as value (strip leading '=')
                        let rest: String = chars[j+1..].iter().collect();
                        if !rest.is_empty() {
                            let v=rest.strip_prefix('=').unwrap_or(&rest).to_string();
                            set_top_option(&mut args,"output",v);
                        } else {
                            if i+1>=argv.len() { missing_value(&format!("{} ",bin),&canon,&used); }
                            let next=argv[i+1].clone();
                            if next=="--" { missing_value(&format!("{} ",bin),&canon,&used); }
                            else if next.starts_with('-') && next!="-" {
                                if is_recognized_flag_token(&next,false) {
                                    pending_missing=Some(canon.clone());
                                    pending_missing_long=Some("output".to_string());
                                } else {
                                    let disp=flag_display(&next);
                                    unknown_argument(bin,&disp,&used,"[FLAGS] [OPTIONS] [input] [SUBCOMMAND]",None,&format!("{} ",bin));
                                }
                            } else {
                                set_top_option(&mut args,"output",next);
                                consumed_next=true;
                            }
                        }
                        j=chars.len();
                    }
                    _=>{
                        let disp=format!("-{}",ch);
                        unknown_argument(bin,&disp,&used,"[FLAGS] [OPTIONS] [input] [SUBCOMMAND]",None,&format!("{} ",bin));
                    }
                }
            }
            if consumed_next { i+=1; }
            i+=1; continue;
        }
        // bare token or after --
        let token_for_similarity = tok.clone();
        if after_dd {
            // subcommand-like tokens error
            let sim_name = token_for_similarity.trim_start_matches('-');
            if tok=="build"||tok=="help"||did_you_mean(sim_name,&["build","help"]).is_some() {
                // but plain filenames starting with '-' like -h sim_name=h did_you_mean None, will be positional below
                if tok.starts_with('-') && did_you_mean(sim_name,&["build","help"]).is_none() {
                    // fallthrough positional
                } else {
                    subcommand_error(bin,&tok,&used);
                }
            }
            // positional
            if args.input.is_none() {
                args.input=Some(tok.clone());
                i+=1; continue;
            } else {
                unknown_argument(bin,&tok,&[],"[FLAGS] [OPTIONS] [input] [SUBCOMMAND]",None,&format!("{} ",bin));
            }
        }
        if tok=="build" {
            args.is_build=true;
            i+=1;
            break;
        }
        if tok=="help" {
            // help mode: rest tokens
            let rest=&argv[i+1..];
            if rest.is_empty() { print_help(bin); }
            if rest.len()==1 && rest[0]=="build" { print_build_help(bin); }
            if rest.len()==1 && rest[0]=="help" { print_help_help(bin); }
            // for multiple, determine offending
            let offending = if rest[0]=="build"||rest[0]=="help" {
                if rest.len()>1 { rest[1].clone() } else { rest[0].clone() }
            } else { rest[0].clone() };
            err_exit(format!("error: The subcommand '{}' wasn't recognized\n\nUSAGE:\n\t{} help <subcommands>...\n\nFor more information try --help\n",offending,bin));
        }
        if did_you_mean(&tok,&["build","help"]).is_some() {
            subcommand_error(bin,&tok,&used);
        }
        if args.input.is_none() {
            args.input=Some(tok.clone());
            i+=1; continue;
        } else {
            unknown_argument(bin,&tok,&[],"[FLAGS] [OPTIONS] [input] [SUBCOMMAND]",None,&format!("{} ",bin));
        }
    }
    if args.is_build {
        // parse remaining argv[i..] as build args
        parse_build(bin,&argv,i,&mut args);
        return args;
    }
    if let Some(canon)=pending_missing {
        let _=pending_missing_long;
        missing_value(&format!("{} ",bin),&canon,&used);
    }
    args
}

fn parse_build(bin:&str, argv:&[String], start:usize, args:&mut TopArgs) {
    let mut used:Vec<String>=Vec::new();
    let mut pending_missing:Option<String>=None;
    let mut after_dd=false;
    let mut i=start;
    while i<argv.len() {
        let tok=argv[i].clone();
        if !after_dd && tok=="--" { after_dd=true; i+=1; continue; }
        if !after_dd && tok.starts_with("--") && tok.len()>2 {
            let body=&tok[2..];
            let (name,inline_val)=match body.find('='){Some(eq)=>(body[..eq].to_string(),Some(body[eq+1..].to_string())),None=>(body.to_string(),None)};
            if name=="help"{print_build_help(bin);}
            if name=="version"{print_build_version(bin);}
            if name=="input"||name=="outdir"{
                let canon=canon_build(&name);
                let present=if name=="input"{args.build_input.is_some()||used.contains(&canon)}else{args.build_outdir.is_some()||used.contains(&canon)};
                if present{duplicate_argument(&format!("{} build ",bin),&canon);}
                used.push(canon.clone());
                if let Some(v)=inline_val{
                    if name=="input"{args.build_input=Some(v);}else{args.build_outdir=Some(v);}
                } else {
                    if i+1>=argv.len(){missing_value(&format!("{} build ",bin),&canon,&used);}
                    let next=argv[i+1].clone();
                    if next=="--"{missing_value(&format!("{} build ",bin),&canon,&used);}
                    else if next.starts_with('-')&&next!="-"{
                        if is_recognized_flag_token(&next,true){pending_missing=Some(canon.clone());}
                        else {let disp=flag_display(&next); unknown_argument(bin,&disp,&used,"[OPTIONS]",None,&format!("{} build ",bin));}
                    } else {
                        if name=="input"{args.build_input=Some(next);}else{args.build_outdir=Some(next);}
                        i+=1;
                    }
                }
                i+=1;continue;
            } else {
                let disp=format!("--{}",name);
                let sug=did_you_mean(&name,&BUILD_LONGS);
                let suggestion=sug.map(|s|(s,canon_build(s)));
                unknown_argument(bin,&disp,&used,"[OPTIONS]",suggestion,&format!("{} build ",bin));
            }
        }
        if !after_dd && tok.starts_with('-') && tok.len()>1 && tok!="-" {
            let chars:Vec<char>=tok.chars().collect();
            let mut j=1usize; let mut consumed_next=false;
            while j<chars.len(){
                let ch=chars[j];
                match ch{
                    'h'=>print_build_help(bin),
                    'V'=>print_build_version(bin),
                    'i'|'o'=>{
                        let long=if ch=='i'{"input"}else{"outdir"};
                        let canon=canon_build(long);
                        let present=if long=="input"{args.build_input.is_some()||used.contains(&canon)}else{args.build_outdir.is_some()||used.contains(&canon)};
                        if present{duplicate_argument(&format!("{} build ",bin),&canon);}
                        used.push(canon.clone());
                        let rest:String=chars[j+1..].iter().collect();
                        if !rest.is_empty(){
                            let v=rest.strip_prefix('=').unwrap_or(&rest).to_string();
                            if long=="input"{args.build_input=Some(v);}else{args.build_outdir=Some(v);}
                        } else {
                            if i+1>=argv.len(){missing_value(&format!("{} build ",bin),&canon,&used);}
                            let next=argv[i+1].clone();
                            if next=="--"{missing_value(&format!("{} build ",bin),&canon,&used);}
                            else if next.starts_with('-')&&next!="-"{
                                if is_recognized_flag_token(&next,true){pending_missing=Some(canon.clone());}
                                else {let disp=flag_display(&next); unknown_argument(bin,&disp,&used,"[OPTIONS]",None,&format!("{} build ",bin));}
                            } else {
                                if long=="input"{args.build_input=Some(next);}else{args.build_outdir=Some(next);}
                                consumed_next=true;
                            }
                        }
                        j=chars.len();
                    }
                    _=>{
                        let disp=format!("-{}",ch);
                        unknown_argument(bin,&disp,&used,"[OPTIONS]",None,&format!("{} build ",bin));
                    }
                }
            }
            if consumed_next{i+=1;}
            i+=1;continue;
        }
        // bare token unexpected
        unknown_argument(bin,&tok,&used,"[OPTIONS]",None,&format!("{} build ",bin));
    }
    if let Some(canon)=pending_missing{missing_value(&format!("{} build ",bin),&canon,&used);}
}

fn illegal<T>(name:&str, val:Option<String>, default:T) -> T
where T: std::str::FromStr, <T as std::str::FromStr>::Err: std::fmt::Display {
    if let Some(v)=val {
        match v.parse::<T>() {
            Ok(x)=>x,
            Err(e)=>{ eprintln!("Illegal value for argument {}: {}",name,e); process::exit(1); }
        }
    } else { default }
}

fn do_build(pattern_opt:Option<String>, outdir_opt:Option<String>) -> ! {
    let pattern = pattern_opt.unwrap_or_else(|| "*.bob".to_string());
    let pattern_path = Path::new(&pattern);
    let dir_path: &Path;
    let dir_owned: PathBuf;
    if pattern_path.is_dir() {
        dir_path = pattern_path;
    } else {
        dir_owned = pattern_path.parent().unwrap().to_path_buf();
        // need to keep lifetime: leak approach via converting below
        // Use a scoped implementation instead:
        return do_build_in_dir(&dir_owned, pattern_path, outdir_opt);
    }
    do_build_in_dir(dir_path, pattern_path, outdir_opt)
}
fn do_build_in_dir(dir:&Path, pattern_path:&Path, outdir_opt:Option<String>) -> ! {
    if !dir.is_dir() {
        println!("[Error]: No such dir name is {} !", dir.display());
        process::exit(1);
    }
    let outdir = outdir_opt.unwrap_or_default();
    if !outdir.is_empty() {
        if let Err(e)=fs::create_dir_all(&outdir) {
            println!("{}",e);
            process::exit(1);
        }
    }
    let ext_default = std::ffi::OsString::from("bob");
    let ext = pattern_path.extension().unwrap_or(&ext_default);
    let entries = fs::read_dir(dir).unwrap();
    for entry in entries {
        let entry = entry.unwrap();
        let path = entry.path();
        if !path.is_file() { continue; }
        if path.extension()!=Some(ext) { continue; }
        let out_path: PathBuf = if outdir.is_empty() {
            path.with_extension("svg")
        } else {
            let mut p=PathBuf::from(&outdir);
            let fname=path.with_extension("svg");
            if let Some(f)=fname.file_name(){p.push(f);}
            p
        };
        println!("{} => {}", path.display(), out_path.display());
        let mut file = fs::File::open(&path).unwrap();
        let mut content=String::new();
        file.read_to_string(&mut content).unwrap();
        let svg=to_svg(&content,&Settings::default());
        if let Err(e)=fs::write(&out_path,svg){
            println!("{}",e);
            process::exit(1);
        }
    }
    process::exit(1)
}

fn main() {
    let bin=bin_name();
    let args=parse_args(&bin);
    if args.is_build {
        do_build(args.build_input.clone(), args.build_outdir.clone());
    }
    // get input text
    let text: String;
    if args.inline {
        text = args.input.clone().unwrap().to_owned();
    } else if let Some(path)=args.input.clone() {
        let mut file = match fs::File::open(&path) {
            Ok(f)=>f,
            Err(e)=>{ eprintln!("Failed to open input file {}: {}",path,e); process::exit(1); }
        };
        let mut s=String::new();
        file.read_to_string(&mut s).unwrap();
        text=s;
    } else {
        let mut s=String::new();
        io::stdin().read_to_string(&mut s).unwrap();
        text=s;
    }
    let mut settings=Settings::default();
    if let Some(v)=args.background.clone(){settings.background=v;}
    if let Some(v)=args.fill_color.clone(){settings.fill_color=v;}
    if let Some(v)=args.stroke_color.clone(){settings.stroke_color=v;}
    if let Some(v)=args.font_family.clone(){settings.font_family=v;}
    settings.font_size=illegal("font-size",args.font_size.clone(),settings.font_size);
    settings.stroke_width=illegal("stroke-width",args.stroke_width.clone(),settings.stroke_width);
    settings.scale=illegal("scale",args.scale.clone(),settings.scale);
    let svg=to_svg(&text,&settings);
    if let Some(out)=args.output.clone() {
        if let Err(e)=fs::write(&out,&svg){
            eprintln!("Failed to write to output file {}: {}",out,e);
            process::exit(2);
        }
    } else {
        println!("{}",svg);
    }
}
