        // We'll override below.
    }
    let usage_final = if suggestion.is_some() { usage } else {
        if used.is_empty() { format!("{}{}",prefix,full) } else { format!("{}{}",prefix,used.join(" ")) }
    };
    msg.push_str(&format!("\nUSAGE:\n    {}\n\nFor more information try --help\n",usage_final));
