#[derive(Default, Clone)]
struct TopArgs {
    inline: bool,
    input: Option<String>,
    output: Option<String>,
    background: Option<String>,
    fill_color: Option<String>,
    stroke_color: Option<String>,
    font_family: Option<String>,
    font_size: Option<String>,
    stroke_width: Option<String>,
    scale: Option<String>,
    build_input: Option<String>,
    build_outdir: Option<String>,
    is_build: bool,
}

const TOP_LONGS:[&str;10]=["help","version","background","fill-color","font-family","font-size","output","scale","stroke-color","stroke-width"];
const BUILD_LONGS:[&str;4]=["help","version","input","outdir"];

fn canon_top(long:&str)->String{
    match long {
        "help"=>"--help".to_string(),
        "version"=>"--version".to_string(),
        _=>format!("--{} <{}>",long,long),
    }
}
fn canon_build(long:&str)->String{
    match long {"help"=>"--help".to_string(),"version"=>"--version".to_string(),_=>format!("--{} <{}>",long,long)}
}
fn set_top_option(args:&mut TopArgs, long:&str, val:String){
    match long {
        "background"=>args.background=Some(val),
        "fill-color"=>args.fill_color=Some(val),
        "stroke-color"=>args.stroke_color=Some(val),
        "font-family"=>args.font_family=Some(val),
        "font-size"=>args.font_size=Some(val),
        "stroke-width"=>args.stroke_width=Some(val),
        "scale"=>args.scale=Some(val),
        "output"=>args.output=Some(val),
        _=>{}
    }
}
fn top_option_present(args:&TopArgs,long:&str)->bool{
    match long {
        "background"=>args.background.is_some(),
        "fill-color"=>args.fill_color.is_some(),
        "stroke-color"=>args.stroke_color.is_some(),
        "font-family"=>args.font_family.is_some(),
        "font-size"=>args.font_size.is_some(),
        "stroke-width"=>args.stroke_width.is_some(),
        "scale"=>args.scale.is_some(),
        "output"=>args.output.is_some(),
        _=>false,
    }
}
fn is_recognized_flag_token(tok:&str, build:bool)->bool{
    if tok.starts_with("--") {
        let name=tok[2..].split('=').next().unwrap_or("");
        if build { BUILD_LONGS.contains(&name) } else { TOP_LONGS.contains(&name) }
    } else if tok.starts_with('-') && tok.len()>1 {
        let first=tok.chars().nth(1).unwrap();
        if build { matches!(first,'h'|'V'|'i'|'o') } else { matches!(first,'h'|'V'|'s'|'o') }
    } else { false }
}
fn flag_display(tok:&str)->String{
    if tok.starts_with("--") {
        format!("--{}",tok[2..].split('=').next().unwrap_or(""))
    } else if tok.starts_with('-') && tok.len()>1 {
        format!("-{}",tok.chars().nth(1).unwrap())
    } else { tok.to_string() }
}

fn parse_args(bin:&str) -> TopArgs {
    let argv:Vec<String>=env::args().skip(1).collect();
    let mut args=TopArgs::default();
    let mut used:Vec<String>=Vec::new();
    let mut seen_s=false;
    let mut pending_missing:Option<String>=None; // canonical display
    let mut pending_missing_long:Option<String>=None;
    let mut after_dd=false;
    let mut i=0usize;
    // helper closures can't easily capture mut; inline code
    while i<argv.len() {
        let tok=argv[i].clone();
        if args.is_build {
            // build parsing handled in separate loop below by breaking with remaining index
            break;
        }
        if !after_dd && tok=="--" { after_dd=true; i+=1; continue; }
        if !after_dd && tok.starts_with("--") && tok.len()>2 {
            let body=&tok[2..];
            let (name, inline_val) = match body.find('=') {
                Some(eq)=>(body[..eq].to_string(), Some(body[eq+1..].to_string())),
                None=>(body.to_string(),None),
            };
            if name=="help" { print_help(bin); }
            if name=="version" { print_version(); }
            if TOP_LONGS.contains(&name.as_str()) {
                let canon=canon_top(&name);
                if top_option_present(&args,&name) || used.contains(&canon) {
                    duplicate_argument(&format!("{} ",bin), &canon);
                }
                used.push(canon.clone());
                if let Some(v)=inline_val {
                    set_top_option(&mut args,&name,v);
                } else {
                    // lookahead
                    if i+1>=argv.len() {
                        missing_value(&format!("{} ",bin), &canon, &used);
                    }
                    let next=argv[i+1].clone();
                    if next=="--" {
                        missing_value(&format!("{} ",bin), &canon, &used);
                    } else if next.starts_with('-') && next!="-" {
                        if is_recognized_flag_token(&next,false) {
                            // check if it's help/version -> next iteration will exit; just mark pending
                            pending_missing=Some(canon.clone());
                            pending_missing_long=Some(name.clone());
                            // set a placeholder? To detect duplicate, used contains canon. Keep option None.
                            // continue without consuming next
                        } else {
                            let disp=flag_display(&next);
                            unknown_argument(bin,&disp,&used,"[FLAGS] [OPTIONS] [input] [SUBCOMMAND]",None,&format!("{} ",bin));
                        }
                    } else {
                        set_top_option(&mut args,&name,next);
                        i+=1;
                    }
                }
                i+=1; continue;
            } else {
                let disp=format!("--{}",name);
                let sug=did_you_mean(&name,&TOP_LONGS);
                let suggestion=sug.map(|s|(s,canon_top(s)));
                unknown_argument(bin,&disp,&used,"[FLAGS] [OPTIONS] [input] [SUBCOMMAND]",suggestion,&format!("{} ",bin));
            }
        }
        if !after_dd && tok.starts_with('-') && tok.len()>1 && tok!="-" {
            // short cluster
            let chars:Vec<char>=tok.chars().collect();
            let mut j=1usize;
            let mut consumed_next=false;
            while j<chars.len() {
                let ch=chars[j];
                match ch {
                    'h'=>print_help(bin),
                    'V'=>print_version(),
                    's'=>{
                        if seen_s { duplicate_argument(&format!("{} ",bin),"-s"); }
                        seen_s=true; args.inline=true;
                        if !used.contains(&"-s".to_string()){used.push("-s".to_string());}
                        j+=1;
                    }
                    'o'=>{
                        let canon=canon_top("output");
                        if top_option_present(&args,"output") || used.contains(&canon) {
                            duplicate_argument(&format!("{} ",bin),&canon);
                        }
                        used.push(canon.clone());
                        // rest of cluster as value (strip leading '=')
                        let rest: String = chars[j+1..].iter().collect();
                        if !rest.is_empty() {
                            let v=rest.strip_prefix('=').unwrap_or(&rest).to_string();
                            set_top_option(&mut args,"output",v);
                        } else {
                            if i+1>=argv.len() { missing_value(&format!("{} ",bin),&canon,&used); }
                            let next=argv[i+1].clone();
                            if next=="--" { missing_value(&format!("{} ",bin),&canon,&used); }
                            else if next.starts_with('-') && next!="-" {
                                if is_recognized_flag_token(&next,false) {
                                    pending_missing=Some(canon.clone());
                                    pending_missing_long=Some("output".to_string());
                                } else {
                                    let disp=flag_display(&next);
                                    unknown_argument(bin,&disp,&used,"[FLAGS] [OPTIONS] [input] [SUBCOMMAND]",None,&format!("{} ",bin));
                                }
                            } else {
                                set_top_option(&mut args,"output",next);
                                consumed_next=true;
                            }
                        }
                        j=chars.len();
                    }
                    _=>{
                        let disp=format!("-{}",ch);
                        unknown_argument(bin,&disp,&used,"[FLAGS] [OPTIONS] [input] [SUBCOMMAND]",None,&format!("{} ",bin));
                    }
                }
            }
            if consumed_next { i+=1; }
            i+=1; continue;
        }
        // bare token or after --
        let token_for_similarity = tok.clone();
        if after_dd {
            // subcommand-like tokens error
            let sim_name = token_for_similarity.trim_start_matches('-');
            if tok=="build"||tok=="help"||did_you_mean(sim_name,&["build","help"]).is_some() {
                // but plain filenames starting with '-' like -h sim_name=h did_you_mean None, will be positional below
                if tok.starts_with('-') && did_you_mean(sim_name,&["build","help"]).is_none() {
                    // fallthrough positional
                } else {
                    subcommand_error(bin,&tok,&used);
                }
            }
            // positional
            if args.input.is_none() {
                args.input=Some(tok.clone());
                i+=1; continue;
            } else {
                unknown_argument(bin,&tok,&[],"[FLAGS] [OPTIONS] [input] [SUBCOMMAND]",None,&format!("{} ",bin));
            }
        }
        if tok=="build" {
            args.is_build=true;
            i+=1;
            break;
        }
        if tok=="help" {
            // help mode: rest tokens
            let rest=&argv[i+1..];
            if rest.is_empty() { print_help(bin); }
            if rest.len()==1 && rest[0]=="build" { print_build_help(bin); }
            if rest.len()==1 && rest[0]=="help" { print_help_help(bin); }
            // for multiple, determine offending
            let offending = if rest[0]=="build"||rest[0]=="help" {
                if rest.len()>1 { rest[1].clone() } else { rest[0].clone() }
            } else { rest[0].clone() };
            err_exit(format!("error: The subcommand '{}' wasn't recognized\n\nUSAGE:\n\t{} help <subcommands>...\n\nFor more information try --help\n",offending,bin));
        }
        if did_you_mean(&tok,&["build","help"]).is_some() {
            subcommand_error(bin,&tok,&used);
        }
        if args.input.is_none() {
            args.input=Some(tok.clone());
            i+=1; continue;
        } else {
            unknown_argument(bin,&tok,&[],"[FLAGS] [OPTIONS] [input] [SUBCOMMAND]",None,&format!("{} ",bin));
        }
    }
    if args.is_build {
        // parse remaining argv[i..] as build args
        parse_build(bin,&argv,i,&mut args);
        return args;
    }
    if let Some(canon)=pending_missing {
        let _=pending_missing_long;
        missing_value(&format!("{} ",bin),&canon,&used);
    }
    args
}

fn parse_build(bin:&str, argv:&[String], start:usize, args:&mut TopArgs) {
    let mut used:Vec<String>=Vec::new();
    let mut pending_missing:Option<String>=None;
    let mut after_dd=false;
    let mut i=start;
    while i<argv.len() {
        let tok=argv[i].clone();
        if !after_dd && tok=="--" { after_dd=true; i+=1; continue; }
        if !after_dd && tok.starts_with("--") && tok.len()>2 {
            let body=&tok[2..];
            let (name,inline_val)=match body.find('='){Some(eq)=>(body[..eq].to_string(),Some(body[eq+1..].to_string())),None=>(body.to_string(),None)};
            if name=="help"{print_build_help(bin);}
            if name=="version"{print_build_version(bin);}
            if name=="input"||name=="outdir"{
                let canon=canon_build(&name);
