                    else if next.starts_with('-')&&next!="-"{
                        if is_recognized_flag_token(&next,true){pending_missing=Some(canon.clone());}
                        else {let disp=flag_display(&next); unknown_argument(bin,&disp,&used,"[OPTIONS]",None,&format!("{} build ",bin));}
                    } else {
                        if name=="input"{args.build_input=Some(next);}else{args.build_outdir=Some(next);}
                        i+=1;
                    }
                }
                i+=1;continue;
            } else {
                let disp=format!("--{}",name);
                let sug=did_you_mean(&name,&BUILD_LONGS);
                let suggestion=sug.map(|s|(s,canon_build(s)));
                unknown_argument(bin,&disp,&used,"[OPTIONS]",suggestion,&format!("{} build ",bin));
            }
        }
        if !after_dd && tok.starts_with('-') && tok.len()>1 && tok!="-" {
            let chars:Vec<char>=tok.chars().collect();
            let mut j=1usize; let mut consumed_next=false;
            while j<chars.len(){
                let ch=chars[j];
                match ch{
                    'h'=>print_build_help(bin),
                    'V'=>print_build_version(bin),
                    'i'|'o'=>{
                        let long=if ch=='i'{"input"}else{"outdir"};
                        let canon=canon_build(long);
                        let present=if long=="input"{args.build_input.is_some()||used.contains(&canon)}else{args.build_outdir.is_some()||used.contains(&canon)};
                        if present{duplicate_argument(&format!("{} build ",bin),&canon);}
                        used.push(canon.clone());
                        let rest:String=chars[j+1..].iter().collect();
                        if !rest.is_empty(){
                            let v=rest.strip_prefix('=').unwrap_or(&rest).to_string();
                            if long=="input"{args.build_input=Some(v);}else{args.build_outdir=Some(v);}
                        } else {
                            if i+1>=argv.len(){missing_value(&format!("{} build ",bin),&canon,&used);}
                            let next=argv[i+1].clone();
                            if next=="--"{missing_value(&format!("{} build ",bin),&canon,&used);}
                            else if next.starts_with('-')&&next!="-"{
                                if is_recognized_flag_token(&next,true){pending_missing=Some(canon.clone());}
                                else {let disp=flag_display(&next); unknown_argument(bin,&disp,&used,"[OPTIONS]",None,&format!("{} build ",bin));}
                            } else {
                                if long=="input"{args.build_input=Some(next);}else{args.build_outdir=Some(next);}
                                consumed_next=true;
                            }
                        }
                        j=chars.len();
                    }
                    _=>{
                        let disp=format!("-{}",ch);
                        unknown_argument(bin,&disp,&used,"[OPTIONS]",None,&format!("{} build ",bin));
                    }
                }
            }
            if consumed_next{i+=1;}
            i+=1;continue;
        }
        // bare token unexpected
        unknown_argument(bin,&tok,&used,"[OPTIONS]",None,&format!("{} build ",bin));
    }
    if let Some(canon)=pending_missing{missing_value(&format!("{} build ",bin),&canon,&used);}
}

fn illegal<T>(name:&str, val:Option<String>, default:T) -> T
where T: std::str::FromStr, <T as std::str::FromStr>::Err: std::fmt::Display {
    if let Some(v)=val {
        match v.parse::<T>() {
            Ok(x)=>x,
            Err(e)=>{ eprintln!("Illegal value for argument {}: {}",name,e); process::exit(1); }
        }
    } else { default }
}

fn do_build(pattern_opt:Option<String>, outdir_opt:Option<String>) -> ! {
    let pattern = pattern_opt.unwrap_or_else(|| "*.bob".to_string());
    let pattern_path = Path::new(&pattern);
    let dir_path: &Path;
    let dir_owned: PathBuf;
    if pattern_path.is_dir() {
        dir_path = pattern_path;
    } else {
        dir_owned = pattern_path.parent().unwrap().to_path_buf();
        // need to keep lifetime: leak approach via converting below
        // Use a scoped implementation instead:
        return do_build_in_dir(&dir_owned, pattern_path, outdir_opt);
    }
    do_build_in_dir(dir_path, pattern_path, outdir_opt)
}
fn do_build_in_dir(dir:&Path, pattern_path:&Path, outdir_opt:Option<String>) -> ! {
    if !dir.is_dir() {
        println!("[Error]: No such dir name is {} !", dir.display());
        process::exit(1);
    }
    let outdir = outdir_opt.unwrap_or_default();
    if !outdir.is_empty() {
        if let Err(e)=fs::create_dir_all(&outdir) {
            println!("{}",e);
            process::exit(1);
        }
    }
    let ext_default = std::ffi::OsString::from("bob");
    let ext = pattern_path.extension().unwrap_or(&ext_default);
    let entries = fs::read_dir(dir).unwrap();
    for entry in entries {
        let entry = entry.unwrap();
        let path = entry.path();
        if !path.is_file() { continue; }
        if path.extension()!=Some(ext) { continue; }
        let out_path: PathBuf = if outdir.is_empty() {
            path.with_extension("svg")
        } else {
            let mut p=PathBuf::from(&outdir);
            let fname=path.with_extension("svg");
            if let Some(f)=fname.file_name(){p.push(f);}
            p
        };
        println!("{} => {}", path.display(), out_path.display());
        let mut file = fs::File::open(&path).unwrap();
        let mut content=String::new();
        file.read_to_string(&mut content).unwrap();
        let svg=to_svg(&content,&Settings::default());
        if let Err(e)=fs::write(&out_path,svg){
            println!("{}",e);
            process::exit(1);
        }
    }
    process::exit(1)
}

fn main() {
    let bin=bin_name();
    let args=parse_args(&bin);
    if args.is_build {
        do_build(args.build_input.clone(), args.build_outdir.clone());
    }
    // get input text
    let text: String;
    if args.inline {
        text = args.input.clone().unwrap().to_owned();
    } else if let Some(path)=args.input.clone() {
        let mut file = match fs::File::open(&path) {
            Ok(f)=>f,
            Err(e)=>{ eprintln!("Failed to open input file {}: {}",path,e); process::exit(1); }
        };
        let mut s=String::new();
        file.read_to_string(&mut s).unwrap();
        text=s;
    } else {
        let mut s=String::new();
        io::stdin().read_to_string(&mut s).unwrap();
        text=s;
    }
    let mut settings=Settings::default();
    if let Some(v)=args.background.clone(){settings.background=v;}
    if let Some(v)=args.fill_color.clone(){settings.fill_color=v;}
    if let Some(v)=args.stroke_color.clone(){settings.stroke_color=v;}
    if let Some(v)=args.font_family.clone(){settings.font_family=v;}
    settings.font_size=illegal("font-size",args.font_size.clone(),settings.font_size);
    settings.stroke_width=illegal("stroke-width",args.stroke_width.clone(),settings.stroke_width);
    settings.scale=illegal("scale",args.scale.clone(),settings.scale);
    let svg=to_svg(&text,&settings);
    if let Some(out)=args.output.clone() {
        if let Err(e)=fs::write(&out,&svg){
            eprintln!("Failed to write to output file {}: {}",out,e);
            process::exit(2);
        }
    } else {
        println!("{}",svg);
    }
}
