import subprocess, string, re
def lines(inp):
    p=subprocess.run(["./executable"],input=inp.encode(),capture_output=True)
    body=p.stdout.decode().split("</defs>")[-1]
    return " | ".join(l.strip() for l in body.splitlines() if l.strip())
for direction in ['E','W']:
  print(direction)
  for c in string.printable:
    if c in ' \t\n\r': continue
    inp = "_"+c if direction=='E' else c+"_"
    out=lines(inp)
    # only print if a line extends beyond underscore cell (x2>8 for E, x1<8 for W underscore at col1)
    ext=False
    for m in re.finditer(r'x1="([0-9.]+)" y1="16" x2="([0-9.]+)" y2="16"', out):
        x1,x2=float(m.group(1)),float(m.group(2))
        if direction=='E' and x2>8: ext=True
        if direction=='W' and x1<8: ext=True
    if ext: print(repr(c),out)
