import subprocess
def body(inp):
    p=subprocess.run(["./executable"],input=inp.encode(),capture_output=True)
    return " | ".join(l.strip() for l in p.stdout.decode().split("</defs>")[-1].splitlines()[1:])
# v at (1,1), neighbor at NW (0,0), NE(2,0)
for target in ['v','^']:
 for direction in ['NW','NE','SW','SE']:
  for nb in ['.','X','/','\\','|','-','+','*','o','(']:
    # place target at (1,1) in 3x3
    g=[[' ',' ',' '],[' ',target,' '],[' ',' ',' ']]
    coords={'NW':(0,0),'NE':(2,0),'SW':(0,2),'SE':(2,2)}
    x,y=coords[direction]; g[y][x]=nb
    inp="\n".join("".join(r) for r in g)
    out=body(inp)
    if '<polygon' in out or '<path' in out or '<line' in out:
        print(target,direction,repr(nb),out)
