import subprocess
def order(inp):
    p=subprocess.run(["./executable"],input=inp.encode(),capture_output=True)
    body=p.stdout.decode().split("</defs>")[-1]
    kinds=[]
    for l in body.splitlines():
        l=l.strip()
        if l.startswith('<line'): kinds.append('L')
        elif l.startswith('<path'): kinds.append('A')
        elif l.startswith('<text'): kinds.append('T')
        elif l.startswith('<rect') and 'backdrop' not in l: kinds.append('R')
        elif l.startswith('<g'): kinds.append('G')
        elif l.startswith('</g'): kinds.append('/G')
    return "".join(kinds)
