import subprocess, sys, itertools
ORIG="/workspace/executable"; NEW="/tmp/newbin/executable"
def run(exe,inp):
    p=subprocess.run([exe],input=inp.encode(),capture_output=True)
    return p.stdout
def bodylines(out):
    s=out.decode(errors='replace').split("</defs>")[-1]
    return [l.strip() for l in s.splitlines() if l.strip() and 'backdrop' not in l and l.strip()!='</svg>']
alphabet="-~_|\\/:=+*#oO.,'`()<>^vVX:a"
mode=sys.argv[1]; start=int(sys.argv[2]); end=int(sys.argv[3])
cases=[]
for tup in itertools.product(alphabet,repeat=3):
    if mode=='h': cases.append("".join(tup))
    elif mode=='v': cases.append("\n".join(tup))
bad_geo=0; bad_order=0; total=0
for idx,t in enumerate(cases[start:end]):
    total+=1
    o=run(ORIG,t); n=run(NEW,t)
    if o==n: continue
    if sorted(bodylines(o))==sorted(bodylines(n)):
        bad_order+=1
        if bad_order<=10: print(f"ORDER idx={start+idx} inp={t!r}")
    else:
        bad_geo+=1
        if bad_geo<=30:
            print(f"\nGEO idx={start+idx} inp={t!r}")
            print(" orig:", " | ".join(bodylines(o)))
            print(" new :", " | ".join(bodylines(n)))
print(f"total={total} geo_bad={bad_geo} order_bad={bad_order} pass={total-bad_geo-bad_order}")
