import subprocess, random, sys
ORIG="/workspace/executable"; NEW="/tmp/newbin/executable"
def diff(t):
    o=subprocess.run([ORIG],input=t.encode(),capture_output=True)
    n=subprocess.run([NEW],input=t.encode(),capture_output=True)
    return (o.returncode,o.stdout,o.stderr)!=(n.returncode,n.stdout,n.stderr)
def get_case(seed,idx,w=5,h=3):
    random.seed(seed)
    alphabet="     -~_|\\/:=+*#oO.,'`()<>^vVXxab    "
    for i in range(idx+1):
        rows=["".join(random.choice(alphabet) for _ in range(w)).rstrip() for __ in range(h)]
        t="\n".join(rows)
    return t
def minimize(t):
    if not diff(t): return None
    changed=True
    while changed:
        changed=False
        lines=[list(r) for r in t.split("\n")]
        coords=[(x,y) for y,row in enumerate(lines) for x,ch in enumerate(row) if ch!=' ']
        for x,y in coords:
            cand=[row[:] for row in lines]; cand[y][x]=' '
            cand_s="\n".join("".join(r).rstrip() for r in cand)
            if diff(cand_s): t=cand_s; changed=True; break
    while True:
        lines=t.split("\n"); cand=None
        if lines and lines[0].strip()=="": cand="\n".join(lines[1:])
        elif lines and lines[-1].strip()=="": cand="\n".join(lines[:-1])
        elif lines and all((len(r)==0 or r[0]==' ') for r in lines): cand="\n".join(r[1:] for r in lines)
        if cand is not None and diff(cand): t=cand
        else: break
    return t
for arg in sys.argv[1:]:
    idx=int(arg); t=get_case(2,idx); m=minimize(t); print(f"case{idx}: {m!r}")
