func = """
fn reassign_marker_stubs(shapes:&mut Vec<Shape>, grid:&Grid, used:&std::collections::BTreeSet<(i32,i32)>) {
    // For each marker cell, if it generated a short marked stub from a focus point to its centre,
    // but an earlier line already touches the marker cell perimeter, that earlier line is the
    // one that should carry the marker (its endpoint moves to the centre), and the stub
    // becomes a plain connector from the focus point to the corresponding boundary point.
    for (mx,my,mc) in grid.sorted_cells() {
        let marker = match Marker::from_char(mc) { Some(m)=>m, None=>continue };
        if used.contains(&(mx,my)) { continue; }
        let ctr=center(mx,my);
        let focuses=[nf(mx,my),sf(mx,my),nwf(mx,my),nef(mx,my),swf(mx,my),sef(mx,my)];
        let boundaries=[north(mx,my),south(mx,my), nw(mx,my), ne(mx,my), sw(mx,my), se(mx,my)];
        // find stub
        let mut stub_idx:Option<usize>=None;
        let mut stub_focus_idx:usize=0;
        let mut stub_is_a_focus=false;
        for (i,sh) in shapes.iter().enumerate() {
            if let ShapeKind::Line{a,b,marker_end,..}=&sh.kind {
                if *marker_end==Some(marker) && pt_eq(*b,ctr) {
                    if let Some(fi)=focuses.iter().position(|&f| pt_eq(f,*a)) { stub_idx=Some(i); stub_focus_idx=fi; stub_is_a_focus=true; break; }
                }
                if *marker_end==Some(marker) && pt_eq(*a,ctr) {
                    // a line starting at centre (should have been flipped, ignore)
                }
            }
        }
        let stub_idx=match stub_idx { Some(v)=>v, None=>continue };
        if !stub_is_a_focus { continue; }
        let stub_seq=shapes[stub_idx].seq;
        // find candidate earlier line with an endpoint on marker perimeter
        let left=mx as f32*8.0; let right=left+8.0; let top=my as f32*16.0; let bottom=top+16.0;
        let mut cand:Option<(usize,bool)>=None; // (index, endpoint_is_b)
        for (i,sh) in shapes.iter().enumerate() {
            if i==stub_idx || sh.seq>=stub_seq { continue; }
            if let ShapeKind::Line{a,b,marker_start,marker_end,..}=&sh.kind {
                if marker_start.is_some() || marker_end.is_some() { continue; }
                for (is_b,pt) in [(false,*a),(true,*b)] {
                    let on_perim = (((pt.y-top).abs()<0.001 || (pt.y-bottom).abs()<0.001) && pt.x>=left-0.001 && pt.x<=right+0.001)
                        || (((pt.x-left).abs()<0.001 || (pt.x-right).abs()<0.001) && pt.y>=top-0.001 && pt.y<=bottom+0.001);
                    if on_perim && !pt_eq(pt,ctr) {
                        cand=Some((i,is_b)); break;
                    }
                }
                if cand.is_some() { break; }
            }
        }
        let (cand_idx,cand_is_b)=match cand { Some(v)=>v, None=>continue };
        // Transform stub into plain connector focus->boundary
        if let ShapeKind::Line{a,..}=&mut shapes[stub_idx].kind {
            let focus=*a;
            shapes[stub_idx].kind=ShapeKind::Line{a:focus,b:boundaries[stub_focus_idx],style:LineStyle::Solid,marker_start:None,marker_end:None};
        }
        // Transform candidate: move its perimeter endpoint to centre and tag it (flip if needed to put marker at end)
        if let ShapeKind::Line{a,b,style,marker_start,marker_end}=shapes[cand_idx].kind.clone() {
            if cand_is_b {
                shapes[cand_idx].kind=ShapeKind::Line{a,b:ctr,style,marker_start,marker_end:Some(marker)};
            } else {
                // flip: new start is old b, new end is centre; preserve any existing end marker as start marker
                shapes[cand_idx].kind=ShapeKind::Line{a:b,b:ctr,style,marker_start:marker_end,marker_end:Some(marker)};
            }
        }
    }
}
"""
