"""fn box_ports(c:char) -> Option<(bool,bool,bool,bool)> {
    // returns (north, west, east, south) intrinsic single-line ports for light box chars
    let p = match c {
        '\\u{250C}' => (false,false,true,true),
        '\\u{2510}' => (false,true,false,true),
        '\\u{2514}' => (true,false,true,false),
        '\\u{2518}' => (true,true,false,false),
        '\\u{251C}' => (true,false,true,true),
        '\\u{2524}' => (true,true,false,true),
        '\\u{252C}' => (false,true,true,true),
        '\\u{2534}' => (true,true,true,false),
        '\\u{253C}' => (true,true,true,true),
        _ => return None,
    };
    Some(p)
}
fn fragments_for(ctx:&Ctx, x:i32,y:i32,c:char) -> Vec<Frag> {""")
# At start of fragments_for body, handle special unicode chars before the main match.
# Insert after "let g = ctx.g;\n    let _ = g;"
s=s.replace("""    let g = ctx.g;
    let _ = g;
    match c {""",
"""    let g = ctx.g;
    // --- Unicode intrinsic graphic characters ---
    if let Some((has_n,has_w,has_e,has_s)) = box_ports(c) {
        let mut frags=Vec::new();
        if has_n { frags.push(line_frag(north(x,y), center(x,y))); }
        if has_w { frags.push(line_frag(west(x,y), center(x,y))); }
        if has_e { frags.push(line_frag(center(x,y), east(x,y))); }
        if has_s { frags.push(line_frag(center(x,y), south(x,y))); }
        return frags;
    }
    match c {
        '\\u{256D}' => return vec![Frag::Arc(east(x,y), sf(x,y), 4.0, false, false), line_frag(sf(x,y), south(x,y))],
        '\\u{256E}' => return vec![Frag::Arc(west(x,y), sf(x,y), 4.0, false, true), line_frag(sf(x,y), south(x,y))],
        '\\u{256F}' => return vec![line_frag(north(x,y), nf(x,y)), Frag::Arc(nf(x,y), west(x,y), 4.0, false, true)],
        '\\u{2570}' => return vec![line_frag(north(x,y), nf(x,y)), Frag::Arc(nf(x,y), east(x,y), 4.0, false, false)],
        '\\u{2573}' => return vec![line_frag(nw(x,y), se(x,y)), line_frag(ne(x,y), sw(x,y))],
